cat > lexer.ts <<'EOF'
export type TokenKind = "number" | "word" | "eof";

export interface Token {
  kind: TokenKind;
  text: string;
  value: number;
  line: number;
  column: number;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let lineStart = 0;
  while (i < source.length) {
