import type { Segment, Vec3 } from "./types";

/** sin/cos in degrees, exact on multiples of 90° so square turns close exactly. */
export function trig(deg: number): [number, number] {
  const r = deg % 360;
  if (r % 90 === 0) {
    switch (((r % 360) + 360) % 360) {
      case 0: return [0, 1];
      case 90: return [1, 0];
      case 180: return [0, -1];
      default: return [-1, 0];
    }
  }
  const rad = (deg * Math.PI) / 180;
  return [Math.sin(rad), Math.cos(rad)];
}

const clean = (n: number) => n + 0; // turns -0 into 0

export class Turtle {
  pos: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];
  penDown = true;
  color = "#16866a";
  width = 3;

  /** Moves by `d` along the heading; returns the new position without applying it. */
  target(d: number): Vec3 {
    const h = this.heading;
    return [
      clean(this.pos[0] + h[0] * d),
      clean(this.pos[1] + h[1] * d),
      clean(this.pos[2] + h[2] * d),
    ];
  }

  segmentTo(to: Vec3): Segment | null {
    const f = this.pos;
    if (!this.penDown || (f[0] === to[0] && f[1] === to[1] && f[2] === to[2])) return null;
    return { from: [f[0], f[1], f[2]], to: [to[0], to[1], to[2]], color: this.color, width: this.width };
  }

  /** Right turn around `up` (clockwise from above). */
  yaw(deg: number): void {
    const [s, c] = trig(deg);
    const h = this.heading, r = this.right;
    this.heading = mix(h, c, r, s);
    this.right = mix(r, c, h, -s);
  }

  /** Nose up around `right`. */
  pitch(deg: number): void {
    const [s, c] = trig(deg);
    const h = this.heading, u = this.up;
    this.heading = mix(h, c, u, s);
    this.up = mix(u, c, h, -s);
  }

  /** Roll right around the heading: up tilts towards right. */
  roll(deg: number): void {
    const [s, c] = trig(deg);
    const u = this.up, r = this.right;
    this.up = mix(u, c, r, s);
    this.right = mix(r, c, u, -s);
  }

  home(): void {
    this.pos = [0, 0, 0];
    this.heading = [0, 1, 0];
    this.right = [1, 0, 0];
    this.up = [0, 0, 1];
  }
}

function mix(a: Vec3, ca: number, b: Vec3, cb: number): Vec3 {
  return [clean(a[0] * ca + b[0] * cb), clean(a[1] * ca + b[1] * cb), clean(a[2] * ca + b[2] * cb)];
}
