describe("reguła białych znaków wokół operatorów binarnych", () => {
  test("operator ze spacjami po obu stronach albo bez spacji jest binarny", () => {
    expect(dist("np 10 - 5")).toBe(5);
    expect(dist("np 10-5")).toBe(5);
    expect(dist("np 2+3*4")).toBe(14);
    expect(dist("np 8/2/2")).toBe(2);
  });
  test("np 10 -5 to np 10 i zbłąkany token -5: błąd w kolumnie myślnika, nic nie rysuje", () => {
    const r = run("np 10 -5", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 7 });
    expect(r.error!.message.length).toBeGreaterThan(5);
  });
  test("spacja tylko po prawej stronie też nie czyni operatora binarnym", () => {
    expect(run("np 10- 5", "2d").error).toMatchObject({ line: 1, column: 6 });
    expect(run("np 10 *5", "2d").error).toMatchObject({ line: 1, column: 7 });
    expect(run("np 10 /5", "2d").error).toMatchObject({ line: 1, column: 7 });
    expect(run("np 10 +5", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("znak po nowej linii liczy się jako biały znak", () => {
    expect(dist("np 10 -\n5")).toBe(5);
  });
});
