    expect(ran("jeśli 1 < 2 [np 1]")).toBe(true);
    expect(ran("jesli 2 < 1 [np 1]")).toBe(false);
    expect(ran("if 2 > 1 [np 1]")).toBe(true);
    expect(ran("if 2 > 2 [np 1]")).toBe(false);
    expect(ran("if 2 = 2 [np 1]")).toBe(true);
    expect(ran("if 2 = 3 [np 1]")).toBe(false);
    expect(ran("if 2 <= 2 [np 1]")).toBe(true);
    expect(ran("if 3 <= 2 [np 1]")).toBe(false);
    expect(ran("if 2 >= 2 [np 1]")).toBe(true);
    expect(ran("if 1 >= 2 [np 1]")).toBe(false);
    expect(ran("if 1 <> 2 [np 1]")).toBe(true);
    expect(ran("if 2 <> 2 [np 1]")).toBe(false);
  });
