import type { Cmp, Expr, Op, Proc, Stmt } from "./ast";
import { COMMAND_BY_WORD, normalizeWord } from "./commands";
import { LogoFault } from "./errors";
import { tokenize, type Token } from "./lexer";

const REPCOUNT = new Set(["nrpowt", "repcount"]);
const PROC_START = new Set(["oto", "to"]);
const PROC_END = new Set(["już", "juz", "end"]);

const BINARY: Record<string, { k: "add" | "sub" | "mul" | "div"; prec: number }> = {
  "+": { k: "add", prec: 1 },
  "-": { k: "sub", prec: 1 },
  "*": { k: "mul", prec: 2 },
  "/": { k: "div", prec: 2 },
};

const word = (t: Token) => normalizeWord(t.text);
const isWord = (t: Token, set: Set<string>) => t.kind === "word" && set.has(word(t));

interface ProcInfo {
  name: string;
  params: string[];
  locals: Set<string>;
}

export function parse(source: string): Stmt[] {
  return new Parser(source).program();
}

class Parser {
  private tokens: Token[];
  private p = 0;
  /** Procedures by lower-case name; bodies are filled in as they are parsed. */
  private procs = new Map<string, Proc>();
  private info = new Map<string, ProcInfo>();
  private globals = new Set<string>();
  private scope: ProcInfo | null = null;
  private repeatDepth = 0;

  constructor(source: string) {
    this.tokens = tokenize(source);
    this.prescan();
  }

  /** Collects procedure signatures and every `niech` target, so names may be used before they are defined. */
  private prescan(): void {
    const t = this.tokens;
    let cur: ProcInfo | null = null;
    for (let k = 0; k < t.length; k++) {
      const tok = t[k];
      if (tok.firstOnLine && isWord(tok, PROC_START) && t[k + 1] && t[k + 1].line === tok.line && t[k + 1].kind === "word") {
        const params: string[] = [];
        for (let j = k + 2; j < t.length && t[j].line === tok.line; j++) {
          if (t[j].kind === "varref") params.push(normalizeWord(t[j].text.slice(1)));
          else if (t[j].kind === "word" && word(t[j]) !== "ma") params.push(word(t[j]));
        }
        cur = { name: word(t[k + 1]), params, locals: new Set() };
        if (!this.info.has(cur.name)) this.info.set(cur.name, cur);
      } else if (tok.firstOnLine && isWord(tok, PROC_END)) {
        cur = null;
      } else if (tok.kind === "word" && COMMAND_BY_WORD.get(word(tok)) === "let" && t[k + 1]?.kind === "word") {
        (cur ? cur.locals : this.globals).add(word(t[k + 1]));
      }
    }
  }

  program(): Stmt[] {
    const out: Stmt[] = [];
    while (this.tokens[this.p].kind !== "eof") {
      const tok = this.tokens[this.p];
      if (tok.firstOnLine && isWord(tok, PROC_START)) this.procedure();
      else out.push(this.statement());
    }
    return out;
  }

  private procedure(): void {
    const t = this.tokens;
    const oto = t[this.p++];
    const nameTok = t[this.p++];
    const name = word(nameTok);
    const params: string[] = [];
    if (t[this.p].line === oto.line) {
      if (t[this.p].kind === "word" && word(t[this.p]) === "ma" && t[this.p + 1].text === ":") {
        this.p += 2;
        for (;;) {
          params.push(word(t[this.p++]));
          if (t[this.p].text === "," && t[this.p].line === oto.line) this.p++;
          else break;
        }
      } else {
        while (t[this.p].kind === "varref" && t[this.p].line === oto.line) params.push(normalizeWord(t[this.p++].text.slice(1)));
      }
    }
    const proc: Proc = { name, params, body: [], tok: oto };
    this.procs.set(name, proc);
    const savedScope = this.scope, savedDepth = this.repeatDepth;
    this.scope = this.info.get(name)!;
    this.repeatDepth = 0;
    while (!(t[this.p].firstOnLine && isWord(t[this.p], PROC_END))) proc.body.push(this.statement());
    this.p++;
    this.scope = savedScope;
    this.repeatDepth = savedDepth;
  }

  private isDeclared(name: string): boolean {
    return this.globals.has(name) || (this.scope !== null && (this.scope.params.includes(name) || this.scope.locals.has(name)));
  }

  private block(): Stmt[] {
    this.p++; // [
    const body: Stmt[] = [];
    while (this.tokens[this.p].text !== "]") body.push(this.statement());
    this.p++; // ]
    return body;
  }

  private statement(): Stmt {
    const t = this.tokens;
    const tok = t[this.p++];
    const id = tok.kind === "word" ? COMMAND_BY_WORD.get(word(tok)) : undefined;
    if (!id) {
      const proc = tok.kind === "word" ? this.callable(word(tok)) : undefined;
      if (proc) return { t: "call", proc, args: proc.params.map(() => this.expression()), tok };
      throw new LogoFault(`Nieoczekiwane „${tok.text}” – w tym miejscu powinno być polecenie.`, tok.line, tok.column);
    }
    switch (id) {
      case "color": {
        const s = t[this.p++];
        return { t: "color", value: s.text.slice(1, -1).toLowerCase(), tok };
      }
      case "let": {
        const nameTok = t[this.p++];
        if (nameTok.kind !== "word" || COMMAND_BY_WORD.has(normalizeWord(nameTok.text))) {
          throw new LogoFault(`„${nameTok.text}” nie może być nazwą zmiennej.`, nameTok.line, nameTok.column);
        }
        return { t: "let", name: word(nameTok), arg: this.expression(), tok };
      }
      case "stop":
        return { t: "stop", tok };
      case "pu":
      case "pd":
        return { t: "cmd", id, arg: null, tok };
      case "if":
      case "ifelse": {
        const left = this.expression();
        const c = t[this.p++];
        const right = this.expression();
        const then = this.block();
        const otherwise = id === "ifelse" ? this.block() : null;
        return { t: "if", left, cmp: c.text as Cmp, right, then, else: otherwise, tok };
      }
      case "repeat": {
        const count = this.expression();
        this.repeatDepth++;
        const body = this.block();
        this.repeatDepth--;
        return { t: "repeat", count, body, tok };
      }
      default:
        return { t: "cmd", id, arg: this.expression(), tok };
    }
  }

  /** A procedure known from the pre-scan (possibly defined later): a stub that receives its body when parsed. */
  private callable(name: string): Proc | undefined {
    const info = this.info.get(name);
    if (!info) return undefined;
    let proc = this.procs.get(name);
    if (!proc) {
      proc = { name, params: info.params, body: [], tok: this.tokens[0] };
      this.procs.set(name, proc);
    }
    return proc;
  }

  /** Shunting-yard over the token stream; stops at the first token that cannot continue the expression. */
  private expression(): Expr {
    const t = this.tokens;
    const start = t[this.p];
    const out: Op[] = [];
    const stack: { op: Op | null; prec: number }[] = []; // op null = "("
    let expectOperand = true;
    for (;;) {
      const tok = t[this.p];
      if (expectOperand) {
        if (tok.kind === "number") {
          out.push({ k: "num", v: tok.value });
          this.p++;
          expectOperand = false;
        } else if (tok.kind === "word" && REPCOUNT.has(word(tok))) {
          if (this.repeatDepth === 0) throw new LogoFault("„nrpowt” można użyć tylko wewnątrz polecenia powtórz.", tok.line, tok.column);
          out.push({ k: "rep" });
          this.p++;
          expectOperand = false;
        } else if ((tok.kind === "word" && !COMMAND_BY_WORD.has(word(tok))) || tok.kind === "varref") {
          const name = normalizeWord(tok.kind === "varref" ? tok.text.slice(1) : tok.text);
          if (!this.isDeclared(name)) throw new LogoFault(`Nieznana nazwa „${tok.text}” – to nie parametr ani zmienna.`, tok.line, tok.column);
          out.push({ k: "var", name });
          this.p++;
          expectOperand = false;
        } else if (tok.text === "(") {
          stack.push({ op: null, prec: 0 });
          this.p++;
        } else if (tok.text === "-") {
          stack.push({ op: { k: "neg" }, prec: 3 });
          this.p++;
        } else if (tok.text === "+") {
          this.p++;
        } else break;
      } else if (tok.kind === "punct" && BINARY[tok.text] && tok.spaceBefore === tok.spaceAfter) {
        const b = BINARY[tok.text];
        while (stack.length && stack[stack.length - 1].op && stack[stack.length - 1].prec >= b.prec) out.push(stack.pop()!.op!);
        stack.push({ op: { k: b.k }, prec: b.prec });
        this.p++;
        expectOperand = true;
      } else if (tok.text === ")" && stack.some((s) => !s.op)) {
        while (stack[stack.length - 1].op) out.push(stack.pop()!.op!);
        stack.pop();
        this.p++;
      } else break;
    }
    while (stack.length) out.push(stack.pop()!.op!);
    return { rpn: out, start };
  }
}
