describe("rekurencja i stop", () => {
  test("procedura może wywoływać samą siebie; stop kończy bieżące wywołanie", () => {
    const r = run("oto f ma: n\n jeśli n = 0 [stop]\n np n\n f n - 1\njuż\nf 3", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([3, 5, 6]);
  });
  test("stop wewnątrz powtórz i warunku kończy całą procedurę, a nie tylko treść", () => {
    const r = run("oto p\n powtorz 5 [np 1 jeśli nrpowt = 2 [stop]]\n np 100\njuż\np\nnp 7", "2d");
    expect(r.segments.map((s) => s.to[1])).toEqual([1, 2, 9]);
  });
  test("stop na najwyższym poziomie kończy program, także z wnętrza powtórz", () => {
    const r = run("np 1 powtorz 3 [np 1 stop] np 50", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([1, 2]);
  });
  test("wzajemna rekurencja", () => {
    const r = run("oto a ma: n\n jeśli n < 1 [stop]\n np 1 b n - 1\njuż\noto b ma: n\n pw 90 a n\njuż\na 2", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to)).toEqual([[0, 1, 0], [1, 1, 0]]);
  });
  test("parametr może nazywać się tak jak procedura: w pozycji polecenia to wywołanie, w argumencie – parametr", () => {
    const r = run("oto bok ma: bok\n np bok\njuż\noto f ma: x\n bok x * 2\njuż\nf 5", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([10]);
  });
});
