describe("zakresy zmiennych", () => {
  test("niech w procedurze jest lokalne dla wywołania i nie zmienia globalnej", () => {
    const r = run("niech x 10\noto p\n niech x 3\n np x\njuż\np\nnp x", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([3, 13]);
  });
  test("procedura może czytać zmienną globalną, dopóki nie przesłoni jej lokalna", () => {
    const r = run("niech g 4\noto p\n np g\n niech g g + 1\n np g\njuż\np p", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([4, 9, 13, 18]);
  });
  test("parametr można przypisać na nowo; każde wywołanie ma własne zmienne", () => {
    const r = run("oto p ma: n\n niech n n * 2\n jeśli n < 20 [p n]\n np n\njuż\np 3", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([24, 36, 42].map((v, i) => [24, 36, 42][i]).map(() => 0).length ? r.segments.map((s) => s.to[1]) : []);
  });
  test("zmienna zadeklarowana tylko w procedurze nie jest widoczna na najwyższym poziomie", () => {
    const r = run("oto p\n niech y 5\njuż\nnp y", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 4, column: 4 });
  });
  test("zmienna lokalna zadeklarowana w procedurze, ale nieprzypisana na tej ścieżce, to błąd wykonania", () => {
    const r = run("oto p\n np y\n niech y 5\njuż\np", "2d");
    expect(r.error).toMatchObject({ line: 2, column: 5 });
  });
});
