describe("dom i czyść", () => {
  test("dom rysuje odcinek do początku (gdy pióro opuszczone) i przywraca orientację", () => {
    const r = run("kolor \"#112233\" grubosc 7 np 10 pw 90 np 10 dom np 5", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => [s.from, s.to, s.color, s.width])).toEqual([
      [[0, 0, 0], [0, 10, 0], "#112233", 7],
      [[0, 10, 0], [10, 10, 0], "#112233", 7],
      [[10, 10, 0], [0, 0, 0], "#112233", 7],
      [[0, 0, 0], [0, 5, 0], "#112233", 7],
    ]);
  });
  test("dom z podniesionym piórem nie rysuje i nie zmienia stanu pióra; w początku nic nie rysuje", () => {
    const r = run("dom pod np 10 dom np 3 opu np 1 home", "2d");
    expect(r.segments.map((s) => [s.from[1], s.to[1]])).toEqual([[3, 4], [4, 0]].map(([a, b]) => [a, b]));
  });
  test("czyść usuwa dotychczasowe odcinki i nic poza tym", () => {
    const r = run("np 10 pw 90 np 10 czyść np 5 CZYSC np 6 cs", "2d");
    expect(r.segments).toEqual([]);
    const r2 = run("np 10 pw 90 np 10 czysc np 5", "2d");
    expect(r2.segments).toEqual([{ from: [10, 10, 0], to: [15, 10, 0], color: "#16866a", width: 3 }]);
  });
  test("clearscreen i cs to aliasy czyść", () => {
    expect(run("np 1 clearscreen", "2d").segments).toEqual([]);
    expect(run("np 1 cs np 2", "2d").segments).toHaveLength(1);
  });
});
