import type { Expr } from "./ast";
import { LogoFault } from "./errors";

export interface EvalContext {
  repcount(): number;
  /** undefined when the variable exists but has no value yet. */
  read(name: string): number | undefined;
}

/** Evaluates a postfix expression; every failure is reported at the expression's first token. */
export function evaluate(e: Expr, ctx: EvalContext): number {
  const fail = (message: string) => new LogoFault(message, e.start.line, e.start.column);
  const st: number[] = [];
  for (const op of e.rpn) {
    switch (op.k) {
      case "num": st.push(op.v); break;
      case "rep": st.push(ctx.repcount()); break;
      case "var": {
        const v = ctx.read(op.name);
        if (v === undefined) throw fail(`Zmienna „${op.name}” nie ma jeszcze wartości.`);
        st.push(v);
        break;
      }
      case "neg": st.push(-st.pop()!); break;
      default: {
        const b = st.pop()!, a = st.pop()!;
        if (op.k === "div" && b === 0) throw fail("Dzielenie przez zero.");
        const v = op.k === "add" ? a + b : op.k === "sub" ? a - b : op.k === "mul" ? a * b : a / b;
        if (!Number.isFinite(v)) throw fail("Wynik wyrażenia nie jest skończoną liczbą.");
        st.push(v + 0);
      }
    }
  }
  return st[0];
}

const NO_NAMES: EvalContext = {
  repcount: () => { throw new Error("name"); },
  read: () => { throw new Error("name"); },
};

/** The value of an expression made only of literals, or undefined if it uses names or fails. */
export function foldConstant(e: Expr): number | undefined {
  try {
    return evaluate(e, NO_NAMES);
  } catch {
    return undefined;
  }
}

export function checkWidth(v: number, at: Expr): void {
  if (!Number.isInteger(v) || v < 1 || v > 12) {
    throw new LogoFault("Grubość musi być liczbą całkowitą od 1 do 12.", at.start.line, at.start.column);
  }
}

export function checkRepeatCount(v: number, at: Expr): void {
  if (!Number.isInteger(v) || v < 0 || v > 10000) {
    throw new LogoFault("Liczba powtórzeń musi być liczbą całkowitą od 0 do 10000.", at.start.line, at.start.column);
  }
}
