describe("błędy składni: polecenia, nawiasy, nawiasy kwadratowe", () => {
  const err = (src: string) => {
    const r = run(src, "2d");
    expect(r.segments).toEqual([]);
    return r.error;
  };
  test("nieznane polecenie i zbłąkane wartości", () => {
    expect(err("np 1\nfoo 10")).toMatchObject({ line: 2, column: 1 });
    expect(err("np 10 20")).toMatchObject({ line: 1, column: 7 });
    expect(err("] np 1")).toMatchObject({ line: 1, column: 1 });
    expect(err("np 10 )")).toMatchObject({ line: 1, column: 7 });
    expect(err('np 1 "#abcdef"')).toMatchObject({ line: 1, column: 6 });
    expect(err("np 1 , np 2")).toMatchObject({ line: 1, column: 6 });
    expect(err("x")).toMatchObject({ line: 1, column: 1 });
  });
  test("niedomknięty [ wskazuje ten nawias, gdy program się kończy; zbędny ] wskazuje siebie", () => {
    expect(err("powtorz 2 [np 1")).toMatchObject({ line: 1, column: 11 });
    expect(err("powtorz 2 [np 1 powtorz 2 [np 1]")).toMatchObject({ line: 1, column: 11 });
    expect(err("np 1 ]")).toMatchObject({ line: 1, column: 6 });
    expect(err("powtorz 2 [np 1]]")).toMatchObject({ line: 1, column: 17 });
  });
  test("niedomknięty ( wskazuje ten nawias na końcu programu, w innym wypadku zły token", () => {
    expect(err("np (1 + 2")).toMatchObject({ line: 1, column: 4 });
    expect(err("np ((1)")).toMatchObject({ line: 1, column: 4 });
    expect(err("np (1 + 2 pw 90")).toMatchObject({ line: 1, column: 11 });
    expect(err("np (3 4)")).toMatchObject({ line: 1, column: 7 });
    expect(err("np ()")).toMatchObject({ line: 1, column: 5 });
  });
  test("warunki: brak porównania, brak [ i brak drugiej treści", () => {
    expect(err("jeśli 1 [np 1]")).toMatchObject({ line: 1, column: 9 });
    expect(err("jeśli 1 < 2 np 1")).toMatchObject({ line: 1, column: 14 });
    expect(err("jeśli 1 < 2")).toMatchObject({ line: 1, column: 1 });
    expect(err("jeżeli 1 < 2 [np 1] np 2")).toMatchObject({ line: 1, column: 21 });
    expect(err("jeżeli 1 < 2 [np 1]")).toMatchObject({ line: 1, column: 1 });
    expect(err("powtorz 3 np 1")).toMatchObject({ line: 1, column: 11 });
  });
  test("głębokość zagnieżdżenia nawiasów kwadratowych: 32 dozwolone, 33 – błąd w 33. nawiasie", () => {
    const nest = (n: number) => "powtorz 1 [".repeat(n) + "np 1" + "]".repeat(n);
    expect(run(nest(32), "2d").error).toBeNull();
    const r = run(nest(33), "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 11 * 32 + 11 });
  });
});
