describe("liczby: tylko dziesiętne literały bez znaku", () => {
  test("1e3, 0x10, 12., 1.2.3, 3a i 007x są błędami w tokenie liczby", () => {
    for (const lit of ["1e3", "0x10", "12.", "1.2.3", "3a", "1_000", "5e-3"]) {
      const r = run(`np 1\nnp ${lit}`, "2d");
      expect(r.segments).toEqual([]);
      expect(r.error).toMatchObject({ line: 2, column: 4 });
    }
  });
