    expect(run("np 1 1e3", "2d").error).toMatchObject({ line: 1, column: 6 });
  });
  test("zera wiodące i końcowe są poprawne", () => {
    expect(run("np 007 np 1.50 np 0.5", "2d").segments.map((s) => s.to[1])).toEqual([7, 8.5, 9]);
  });
});
