describe("błędy procedur", () => {
  const err = (src: string) => {
    const r = run(src, "2d");
    expect(r.segments).toEqual([]);
    return r.error;
  };
  const P = "oto kw ma: a, b\n np a\njuż\n";
  test("zła liczba argumentów: za mało – brak argumentu, za dużo – zbłąkana wartość", () => {
    expect(err(P + "kw 5\nnp 1")).toMatchObject({ line: 5, column: 1 });
    expect(err(P + "kw")).toMatchObject({ line: 4, column: 1 });
    expect(err(P + "kw 1 2 3")).toMatchObject({ line: 4, column: 8 });
    expect(err("oto z\n np 1\njuż\nz 5")).toMatchObject({ line: 4, column: 3 });
  });
  test("definicja wewnątrz powtórz, warunku, procedury albo nie na początku linii", () => {
    expect(err("powtorz 2 [\noto a\n np 1\njuż\n]")).toMatchObject({ line: 2, column: 1 });
    expect(err("jeśli 1 < 2 [\noto a\n np 1\njuż\n]")).toMatchObject({ line: 2, column: 1 });
    expect(err("oto a\noto b\n np 1\njuż\njuż")).toMatchObject({ line: 2, column: 1 });
    expect(err("np 1 oto a\n np 1\njuż")).toMatchObject({ line: 1, column: 6 });
  });
  test("brak już wskazuje oto; już samotne lub nie w osobnej linii to błąd", () => {
    expect(err("np 1\noto a\n np 1")).toMatchObject({ line: 2, column: 1 });
    expect(err("np 1\njuż")).toMatchObject({ line: 2, column: 1 });
    expect(err("oto a\n np 1 już")).toMatchObject({ line: 2, column: 7 });
    expect(err("oto a\n np 1\njuż np 2")).toMatchObject({ line: 3, column: 1 });
    expect(err("oto a\n np 1\njuż ; komentarz po już jest dozwolony\nnp 'x'")).toMatchObject({ line: 4, column: 4 });
  });
  test("komentarz po już jest dozwolony", () => {
    expect(run("oto a\n np 1\njuż ; koniec\na", "2d").error).toBeNull();
  });
  test("nazwy: duplikat procedury, słowo kluczowe, zmienna o nazwie procedury, zdublowany parametr", () => {
    expect(err("oto a\njuż\noto A\njuż")).toMatchObject({ line: 3, column: 5 });
    expect(err("oto np\njuż")).toMatchObject({ line: 1, column: 5 });
    expect(err("oto nrpowt\njuż")).toMatchObject({ line: 1, column: 5 });
    expect(err("oto a\njuż\nniech a 5")).toMatchObject({ line: 3, column: 7 });
    expect(err("oto a ma: x, X\njuż")).toMatchObject({ line: 1, column: 14 });
    expect(err("oto a ma: np\njuż")).toMatchObject({ line: 1, column: 11 });
    expect(err("niech nrpowt 5")).toMatchObject({ line: 1, column: 7 });
  });
  test("nagłówek: brak nazwy, ma: bez parametrów, brak przecinka", () => {
    expect(err("oto\n np 1\njuż")).toMatchObject({ line: 1, column: 1 });
    expect(err("oto 5\njuż")).toMatchObject({ line: 1, column: 5 });
    expect(err("oto a ma:\n np 1\njuż")).toMatchObject({ line: 1, column: 9 });
    expect(err("oto a ma: x y\njuż")).toMatchObject({ line: 1, column: 13 });
    expect(err("oto a ma: x,\njuż")).toMatchObject({ line: 1, column: 12 });
  });
  test("nrpowt w treści procedury musi stać leksykalnie w powtórz, nawet jeśli wywołanie jest w powtórz", () => {
    expect(err("oto a\n np nrpowt\njuż\npowtorz 3 [a]")).toMatchObject({ line: 2, column: 5 });
    const ok = run("oto a\n powtorz 2 [np nrpowt]\njuż\npowtorz 3 [a]", "2d");
    expect(ok.error).toBeNull();
    expect(ok.segments.map((s) => s.to[1])).toEqual([1, 3, 4, 6, 7, 9]);
  });
});
EOF
