cat >> tests/interpreter.test.ts <<'EOF'

describe("limity", () => {
  test("źródło dłuższe niż 50 000 znaków jest odrzucane (błąd wskazuje pierwszy nadmiarowy znak), 50 000 jest w porządku", () => {
    const pad = (n: number) => ";" + "x".repeat(n - 1);
    expect(run(pad(50000), "2d").error).toBeNull();
    const r = run(pad(50001), "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 50001 });
  });
  test("10 000 tokenów jest dozwolone, 10 001. to błąd (operatory, nawiasy i przecinki też są tokenami)", () => {
    expect(run("np 1 ".repeat(5000), "2d").error).toBeNull();
    const r = run("np 1 ".repeat(5000) + "np", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 25001 });
    expect(run("np " + "(".repeat(4999) + "1" + ")".repeat(4999), "2d").error).toBeNull();
    expect(run("np " + "(".repeat(5000) + "1" + ")".repeat(5000), "2d").error).toMatchObject({ line: 1, column: 5004 });
  });
  test("10 000 operacji: powtórz liczy się raz, każda iteracja kosztuje treść plus jeden", () => {
    expect(run("powtorz 9999 []", "2d").error).toBeNull();
    const r = run("powtorz 10000 []", "2d");
    expect(r.error).toMatchObject({ line: 1, column: 1 });
    expect(run("powtorz 4999 [np 1]", "2d")).toMatchObject({ error: null });
    const half = run("powtorz 5000 [np 1]", "2d");
    expect(half.segments).toHaveLength(5000);
    expect(half.error).toMatchObject({ line: 1, column: 1 });
  });
  test("niech, warunki i wywołania procedur też kosztują", () => {
    expect(run("powtorz 3333 [niech x 1 niech y 2]", "2d").error).toBeNull();
    expect(run("powtorz 3334 [niech x 1 niech y 2]", "2d").error).not.toBeNull();
    expect(run("powtorz 2499 [jeśli 1 = 1 [np 0]]", "2d").error).toBeNull();
    expect(run("powtorz 2500 [jeśli 1 = 1 [np 0]]", "2d").error).not.toBeNull();
    expect(run("powtorz 4999 [jeśli 1 = 2 [np 1]]", "2d").error).toBeNull();
    expect(run("powtorz 5000 [jeśli 1 = 2 [np 1]]", "2d").error).not.toBeNull();
    const P = "oto p\n np 0\njuż\n";
    expect(run(P + "powtorz 2499 [p]", "2d").error).toBeNull();
    expect(run(P + "powtorz 2500 [p]", "2d").error).not.toBeNull();
  });
  test("najwyżej 32 aktywne ramki wywołań i powtórzeń; błąd w wywołaniu, które przekroczyło limit", () => {
    const r = run("oto r ma: n\n np 1\n r n\njuż\nr 0", "2d");
    expect(r.segments).toHaveLength(32);
    expect(r.error).toMatchObject({ line: 3, column: 2 });
    const mixed = run("oto r\n powtorz 1 [r]\njuż\nr", "2d");
    expect(mixed.error).toMatchObject({ line: 2, column: 13 });
    expect(run("powtorz 1 [".repeat(32) + "np 1" + "]".repeat(32), "2d").error).toBeNull();
  });
  test("warunki nie zajmują ramek: głęboka rekurencja przez jeśli do limitu 32 wywołań", () => {
    const ok = run("oto r ma: n\n jeśli n > 0 [r n - 1]\njuż\nr 31", "2d");
    expect(ok.error).toBeNull();
    expect(run("oto r ma: n\n jeśli n > 0 [r n - 1]\njuż\nr 32", "2d").error).not.toBeNull();
  });
  test("współrzędne w granicach ±100 000; przekroczenie zatrzymuje program w poleceniu ruchu", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    expect(run("ws 100000", "2d").error).toBeNull();
    const r = run("np 60000\nnp 40000\nnp 1", "2d");
    expect(r.segments).toHaveLength(2);
    expect(r.error).toMatchObject({ line: 3, column: 1 });
    const left = run("pw 90 np 50 ws 100001", "2d");
    expect(left.error).toMatchObject({ line: 1, column: 15 });
    expect(left.segments).toHaveLength(1);
  });
  test("wynik niebędący liczbą skończoną to błąd wykonania", () => {
    const r = run("niech x 1000000000\nnp 5\nniech x x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x * x", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 3, column: 9 });
  });
});
EOF
bun run test 2>&1 | grep -E "^\(fail|pass|fail|error" | head -12

