    const r = run("oto r ma: n\n np 1\n r n\njuż\nr 0", "2d");
    expect(r.segments).toHaveLength(32);
    expect(r.error).toMatchObject({ line: 3, column: 2 });
    const mixed = run("oto r\n powtorz 1 [r]\njuż\nr", "2d");
    expect(mixed.error).toMatchObject({ line: 2, column: 13 });
    expect(run("powtorz 1 [".repeat(32) + "np 1" + "]".repeat(32), "2d").error).toBeNull();
  });
  test("warunki nie zajmują ramek: głęboka rekurencja przez jeśli do limitu 32 wywołań", () => {
    const ok = run("oto r ma: n\n jeśli n > 0 [r n - 1]\njuż\nr 31", "2d");
    expect(ok.error).toBeNull();
    expect(run("oto r ma: n\n jeśli n > 0 [r n - 1]\njuż\nr 32", "2d").error).not.toBeNull();
  });
  test("współrzędne w granicach ±100 000; przekroczenie zatrzymuje program w poleceniu ruchu", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    expect(run("ws 100000", "2d").error).toBeNull();
