import { describe, expect, test } from "bun:test";
import { EXAMPLES, getExample } from "../src/data/examples";
import { run, type Segment } from "../src/lang";

const runExample = (id: string) => {
  const ex = getExample(id)!;
  const r = run(ex.source, ex.mode);
  expect(r.error).toBeNull();
  return r.segments;
};
const close = (a: number[], b: number[], eps = 1e-6) => a.every((v, i) => Math.abs(v - b[i]) < eps);
const length = (s: Segment) => Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);

describe("wbudowane programy", () => {
  test("trzynaście programów pod właściwymi nazwami i w właściwych trybach", () => {
    expect(EXAMPLES.map((e) => [e.id, e.mode])).toEqual([
      ["kwadrat", "2d"], ["gwiazda", "2d"], ["rozeta", "2d"], ["spirala", "2d"], ["wielokaty", "2d"],
      ["drzewo", "2d"], ["sniezynka", "2d"], ["schody", "3d"], ["szescian", "3d"], ["pierscien", "3d"],
      ["kula", "3d"], ["helisa", "3d"], ["drzewo3d", "3d"],
    ]);
    expect(getExample("kwadrat")!.source.startsWith("; Cztery boki, cztery skręty.\nkolor \"#16866a\"")).toBe(true);
  });
  test("każdy program działa bez błędu w swoim trybie", () => {
    for (const e of EXAMPLES) expect(run(e.source, e.mode).error).toBeNull();
  });
  test("kwadrat: cztery boki po 120, domknięty", () => {
    const s = runExample("kwadrat");
    expect(s.map((x) => x.to)).toEqual([[0, 120, 0], [120, 120, 0], [120, 0, 0], [0, 0, 0]]);
    expect(s.every((x) => x.color === "#16866a" && x.width === 3)).toBe(true);
  });
  test("gwiazda: pięć ramion po 180 w kolorze #c1763d, wraca do początku", () => {
    const s = runExample("gwiazda");
    expect(s).toHaveLength(5);
    expect(s.every((x) => Math.abs(length(x) - 180) < 1e-9 && x.color === "#c1763d")).toBe(true);
    expect(close(s[4].to, [0, 0, 0])).toBe(true);
  });
  test("rozeta: 12 kwadratów po 4 boki, grubość 2", () => {
    const s = runExample("rozeta");
    expect(s).toHaveLength(48);
    expect(s.every((x) => x.width === 2 && Math.abs(length(x) - 100) < 1e-9)).toBe(true);
    expect(close(s[47].to, [0, 0, 0])).toBe(true);
  });
  test("spirala: 90 boków o długości 2.5·n, kolory na zmianę od zielonego", () => {
    const s = runExample("spirala");
    expect(s).toHaveLength(90);
    expect(s.every((x, i) => Math.abs(length(x) - 2.5 * (i + 1)) < 1e-9)).toBe(true);
    expect(s.slice(0, 4).map((x) => x.color)).toEqual(["#16866a", "#c1763d", "#16866a", "#c1763d"]);
  });
  test("wielokąty: figury od trójkąta do dziewięciokąta, razem 42 boki po 60", () => {
    const s = runExample("wielokaty");
    expect(s).toHaveLength(3 + 4 + 5 + 6 + 7 + 8 + 9);
    expect(s.every((x) => Math.abs(length(x) - 60) < 1e-9)).toBe(true);
    expect(s[0].to).toEqual([0, 60, 0]);
  });
  test("drzewo: 255 gałęzi (osiem poziomów rozgałęzień od 90 do 7.4), pień brązowy", () => {
    const s = runExample("drzewo");
    expect(s).toHaveLength(255);
    expect(s[0]).toEqual({ from: [0, -120, 0], to: [0, -30, 0], color: "#6b4f2a", width: 3 });
  });
  test("śnieżynka: trzy boki po 4^4 odcinków", () => {
    const s = runExample("sniezynka");
    expect(s).toHaveLength(3 * 256);
    expect(s.every((x) => x.color === "#2b6fb3" && x.width === 1)).toBe(true);
    expect(s.every((x) => Math.abs(length(x) - 270 / 81) < 1e-9)).toBe(true);
  });
  test("schody: 12 odcinków, żółw kończy 210 do przodu i 120 w górę", () => {
    const s = runExample("schody");
    expect(s).toHaveLength(12);
    expect(close(s[11].to, [0, 210, 120])).toBe(true);
  });
  test("sześcian: wszystkie wierzchołki w {0,100}³ (17 odcinków, krawędzie rysowane dwa razy)", () => {
    const s = runExample("szescian");
    expect(s).toHaveLength(17);
    for (const x of s) for (const p of [x.from, x.to]) expect(p.every((c) => Math.abs(c) < 1e-9 || Math.abs(c - 100) < 1e-9)).toBe(true);
    const zs = s.flatMap((x) => [x.from[2], x.to[2]]);
    expect(Math.max(...zs)).toBeCloseTo(100, 6);
    expect(Math.min(...zs)).toBeCloseTo(0, 6);
  });
  test("pierścień: 36 boków po 12, okrąg przechylony o 30° sięga ±34.4 w pionie", () => {
    const s = runExample("pierscien");
    expect(s).toHaveLength(36);
    expect(close(s[35].to, [0, 0, 0])).toBe(true);
    const zs = s.flatMap((x) => [x.from[2], x.to[2]]);
    expect(Math.max(...zs)).toBeCloseTo(34.42, 1);
    expect(Math.min(...zs)).toBeCloseTo(-34.42, 1);
  });
  test("kula: 12 okręgów po 36 odcinków, każdy domyka się w początku, kolory na zmianę", () => {
    const s = runExample("kula");
    expect(s).toHaveLength(12 * 36);
    for (let c = 0; c < 12; c++) {
      expect(close(s[c * 36 + 35].to, [0, 0, 0], 1e-6)).toBe(true);
      expect(s[c * 36].color).toBe(c % 2 === 0 ? "#16866a" : "#2b6fb3");
    }
  });
  test("helisa: 240 odcinków, wznosi się o 1.5 na zwój-krok, razem 180", () => {
    const s = runExample("helisa");
    expect(s).toHaveLength(240);
    expect(s[239].to[2]).toBeCloseTo(180, 6);
  });
  test("drzewo 3D: 121 gałęzi (pięć poziomów po trzy odgałęzienia)", () => {
    const s = runExample("drzewo3d");
    expect(s).toHaveLength(121);
    expect(s[0].to[0]).toBeCloseTo(0, 6);
    expect(s[0].to[2]).toBeCloseTo(70, 6);
  });
});
EOF
