mkdir -p src/core && cat > src/lang/session.ts <<'EOF'
import { LogoFault } from "./errors";
import { Machine } from "./machine";
import { parse } from "./parser";
import type { Turtle } from "./turtle";
import type { LogoError, Mode, Segment } from "./types";

/** A program being executed one statement at a time (the engine behind run, step and the animation). */
export class Session {
  error: LogoError | null = null;

  private constructor(private machine: Machine) {}

  /** Parses `source`; a parse-time error yields an error result and no session. */
  static start(source: string, mode: Mode): Session | { error: LogoError } {
    try {
      return new Session(new Machine(parse(source, mode)));
    } catch (e) {
      if (e instanceof LogoFault) return { error: e.toResult() };
      throw e;
    }
  }

  get done(): boolean {
    return this.error !== null || this.machine.done;
  }

  get segments(): Segment[] {
    return this.machine.segments;
  }

  get turtle(): Turtle {
    return this.machine.turtle;
  }

  /** 1-based line and column of the statement that executes next; null when finished. */
  get next(): { line: number; column: number } | null {
    const t = this.done ? null : this.machine.next;
    return t ? { line: t.line, column: t.column } : null;
  }

  /** Executes one statement. A run-time error is recorded in `error` and keeps the drawing. */
  step(): void {
    if (this.done) return;
    try {
      this.machine.step();
    } catch (e) {
      if (!(e instanceof LogoFault)) throw e;
      this.error = e.toResult();
    }
  }
}
EOF
cat > src/lang/index.ts <<'EOF'
import { Session } from "./session";
import type { Mode, RunResult } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";
export { Session } from "./session";
export type { Turtle } from "./turtle";

/** Interprets `source` to the end. A parse-time error draws nothing; a run-time error keeps what was drawn. */
export function run(source: string, mode: Mode): RunResult {
  const session = Session.start(source, mode);
  if ("error" in session) return { segments: [], error: session.error };
  while (!session.done) session.step();
  return { segments: session.segments, error: session.error };
}
