import { Session, type LogoError, type Mode, type Segment } from "../lang";
import type { KeyValueStore } from "./storage";

export type Status = "idle" | "running" | "paused" | "finished" | "error";

export interface WorkspaceState {
  mode: Mode;
  source: string;
  status: Status;
  segments: Segment[];
  currentLine: number | null;
  error: LogoError | null;
  speed: number;
}

/** Statements that one tick may execute at most, so "maximum speed" cannot freeze the page. */
const TICK_BATCH = 20000;

export class Workspace {
  state: WorkspaceState = { mode: "2d", source: "", status: "idle", segments: [], currentLine: null, error: null, speed: 10 };
  private session: Session | null = null;
  private budget = 0;
  private listeners = new Set<() => void>();

  constructor(private deps: { storage: KeyValueStore }) {}

  subscribe(fn: () => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  private update(patch: Partial<WorkspaceState>): void {
    this.state = { ...this.state, ...patch };
    for (const fn of this.listeners) fn();
  }

  setMode(mode: Mode): void {
    this.update({ mode });
  }

  setSource(source: string): void {
    this.update({ source });
  }

  setSpeed(speed: number): void {
    this.update({ speed });
  }

  /** Parses the program and starts a session; false (with the error in the state) when it does not parse. */
  private start(): boolean {
    const s = Session.start(this.state.source, this.state.mode);
    if (!(s instanceof Session)) return false;
    this.session = s;
    this.budget = 0;
    return true;
  }

  private sync(): void {
    const session = this.session!;
    const next = session.next;
    this.update({
      segments: [...session.segments],
      currentLine: next ? next.line : null,
    });
  }

  run(): void {
    if (!this.start()) return;
    this.sync();
    this.update({ status: "running" });
  }

  step(): void {
    if (!this.session && !this.start()) return;
    this.session!.step();
    this.sync();
    this.update({ status: this.session!.done ? "finished" : "paused" });
  }

  /** Advances the animation by `ms` milliseconds of wall-clock time. */
  tick(ms: number): void {
    if (this.state.status !== "running" || !this.session) return;
    const session = this.session;
    this.budget += (ms * this.state.speed) / 1000;
    let n = Math.min(Math.floor(this.budget), TICK_BATCH);
    this.budget -= n;
    while (n-- > 0 && !session.done) session.step();
    if (this.state.speed === Infinity) this.budget = 0;
    this.sync();
    if (session.done) this.update({ status: "finished" });
  }
}
