/** The part of Web Storage the app depends on; injected so it can be replaced in tests. */
export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export const KEY_PREFIX = "logomocja:";

/** Reads and writes under the app prefix and never throws (private mode, quota, disabled storage). */
export function safeStore(store: KeyValueStore) {
  return {
    get(key: string): string | null {
      try {
        return store.getItem(KEY_PREFIX + key);
      } catch {
        return null;
      }
    },
    set(key: string, value: string): void {
      try {
        store.setItem(KEY_PREFIX + key, value);
      } catch {
        /* the app keeps working without persistence */
      }
    },
    remove(key: string): void {
      try {
        store.removeItem(KEY_PREFIX + key);
      } catch {
        /* ignore */
      }
    },
  };
}

export type SafeStore = ReturnType<typeof safeStore>;
