import type { Mode } from "../lang";

export interface SharedProgram {
  source: string;
  mode: Mode;
}

const toBase64Url = (text: string): string => {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};

const fromBase64Url = (data: string): string | null => {
  try {
    const bin = atob(data.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
};

/** The hash route of the workspace carrying a program: `#/?m=3d&p=...`. */
export function shareHash(source: string, mode: Mode): string {
  return `#/?m=${mode}&p=${toBase64Url(source)}`;
}

/** Accepts a full URL or just its hash; null when it carries no (valid) program. */
export function parseShare(link: string): SharedProgram | null {
  const hashAt = link.indexOf("#");
  if (hashAt < 0) return null;
  const route = link.slice(hashAt + 1);
  const q = route.indexOf("?");
  const path = q < 0 ? route : route.slice(0, q);
  if (path !== "" && path !== "/") return null;
  if (q < 0) return null;
  const params = new URLSearchParams(route.slice(q + 1));
  const p = params.get("p");
  if (p === null) return null;
  const source = fromBase64Url(p);
  if (source === null) return null;
  return { source, mode: params.get("m") === "3d" ? "3d" : "2d" };
}
