describe("pliki .logo", () => {
  test("eksport daje dokładnie tekst programu w pliku z rozszerzeniem .logo i trybem w nazwie", () => {
    const { ws } = make();
    ws.setSource("np 1 ; zażółć\n");
    expect(ws.exportFile()).toEqual({ filename: "program-2d.logo", text: "np 1 ; zażółć\n" });
    ws.setMode("3d");
    expect(ws.exportFile().filename).toBe("program-3d.logo");
  });
  test("import wczytuje plik do szkicu; nazwa z -3d / -2d wybiera tryb, w przeciwnym razie tryb się nie zmienia", () => {
    const { ws } = make();
    ws.importFile("moja-helisa-3d.logo", "gora 90 np 5");
    expect(ws.state).toMatchObject({ mode: "3d", source: "gora 90 np 5" });
    ws.importFile("cokolwiek.logo", "np 7");
    expect(ws.state).toMatchObject({ mode: "3d", source: "np 7" });
    ws.importFile("plaski-2d.logo", "np 8");
    expect(ws.state).toMatchObject({ mode: "2d", source: "np 8" });
  });
  test("eksport i import są wzajemnie odwrotne", () => {
    const a = make().ws;
    a.setMode("3d");
    a.setSource("; test\nkolor \"#a478c0\"\nnp 3\n");
    const f = a.exportFile();
    const b = make().ws;
    b.importFile(f.filename, f.text);
    expect(b.state).toMatchObject({ mode: "3d", source: a.state.source });
  });
  test("BOM i zakończenia linii CRLF z Windows są normalizowane, więc kolumny błędów się zgadzają", () => {
    const { ws } = make();
    ws.importFile("a.logo", "﻿np 1\r\nfoo\r\n");
    expect(ws.state.source).toBe("np 1\nfoo\n");
  });
  test("import nie niszczy cicho własnego szkicu", () => {
    const { ws } = make();
    ws.setSource("np 1 ; mój");
    ws.importFile("x.logo", "np 2");
    expect(ws.state.backup).toEqual({ mode: "2d", source: "np 1 ; mój" });
  });
});
