import { describe, expect, test } from "bun:test";
import { ChallengeBook, CHALLENGES } from "../src/core/challenges";
import { run } from "../src/lang";
import { MemoryStorage } from "./helpers";

const book = (storage = new MemoryStorage()) => ({ book: new ChallengeBook(storage), storage });

describe("zadania", () => {
  test("jest co najmniej pięć zadań z unikalnymi identyfikatorami, opisem i obu trybów", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
    expect(CHALLENGES.every((c) => c.title.length > 0 && c.brief.length > 20)).toBe(true);
    expect(CHALLENGES.some((c) => c.mode === "2d") && CHALLENGES.some((c) => c.mode === "3d")).toBe(true);
  });
  test("rozwiązanie wzorcowe każdego zadania zalicza to zadanie, a cel jest niepustym rysunkiem", () => {
    for (const c of CHALLENGES) {
      const { book: b } = book();
      expect(c.target().length).toBeGreaterThan(0);
      expect(b.submit(c.id, c.solution)).toMatchObject({ passed: true });
    }
  });
});

describe("sprawdzanie rozwiązań", () => {
  test("inne, równoważne rozwiązanie (te same krawędzie w innej kolejności) też przechodzi", () => {
    const { book: b } = book();
    const v = b.submit("kwadrat-100", "pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100");
    expect(v.passed).toBe(true);
  });
  test("rysunek w tolerancji przechodzi, spoza tolerancji nie", () => {
    const { book: b } = book();
    expect(b.submit("kwadrat-100", "powtorz 4 [np 100.5 pw 90]").passed).toBe(true);
    const big = b.submit("kwadrat-100", "powtorz 4 [np 105 pw 90]");
    expect(big.passed).toBe(false);
    expect(big.reason.length).toBeGreaterThan(10);
  });
  test("brak rysunku, błąd w programie, brakujące i nadmiarowe odcinki mają osobne powody", () => {
    const { book: b } = book();
    expect(b.submit("kwadrat-100", "").reason).toContain("nic nie narysowano");
    const bad = b.submit("kwadrat-100", "np 100 foo");
    expect(bad).toMatchObject({ passed: false, error: { line: 1, column: 8 } });
    expect(bad.reason).toContain("błęd");
    const missing = b.submit("kwadrat-100", "np 100 pw 90 np 100 pw 90 np 100");
    expect(missing.passed).toBe(false);
    expect(missing.reason).toContain("Brakuje");
    const extra = b.submit("kwadrat-100", "powtorz 4 [np 100 pw 90] np 50");
    expect(extra.passed).toBe(false);
    expect(extra.reason).toContain("nadmiar");
  });
  test("rysunek wiele razy dłuższy od oczekiwanego jest odrzucany szybko", () => {
    const { book: b } = book();
    const v = b.submit("kwadrat-100", "powtorz 3000 [np 99999 ws 99999]");
    expect(v.passed).toBe(false);
  });
  test("kolor nie ma znaczenia, chyba że zadanie go wymaga", () => {
    const { book: b } = book();
    expect(b.submit("kwadrat-100", 'kolor "#c1763d" grubosc 9 powtorz 4 [np 100 pw 90]').passed).toBe(true);
    expect(b.submit("kolorowy-trojkat", "powtorz 3 [np 100 pw 120]")).toMatchObject({ passed: false });
    expect(b.submit("kolorowy-trojkat", "powtorz 3 [np 100 pw 120]").reason).toContain("kolor");
    expect(b.submit("kolorowy-trojkat", 'kolor "#2B6FB3" powtorz 3 [np 100 pw 120]').passed).toBe(true);
  });
  test("zadania 3D sprawdzają położenie w przestrzeni", () => {
    const { book: b } = book();
    expect(b.submit("pionowy-kwadrat", "powtorz 4 [np 80 gora 90]").passed).toBe(true);
    expect(b.submit("pionowy-kwadrat", "powtorz 4 [np 80 pw 90]").passed).toBe(false);
    expect(b.submit("pionowy-kwadrat", "powtorz 4 [np 80 pp 90 gora 90]").passed).toBe(false);
  });
  test("nieznane zadanie zgłasza błąd", () => {
    expect(() => book().book.submit("nie-ma", "np 1")).toThrow();
  });
});

describe("postęp zadań", () => {
  test("zaliczenie jest zapamiętane między sesjami, kolejne próby go nie cofają, liczone są próby", () => {
    const { book: b, storage } = book();
    b.submit("kwadrat-100", "np 1");
    expect(b.results()["kwadrat-100"]).toEqual({ passed: false, attempts: 1 });
    b.submit("kwadrat-100", "powtorz 4 [np 100 pw 90]");
    b.submit("kwadrat-100", "np 2");
    const again = new ChallengeBook(storage);
    expect(again.results()["kwadrat-100"]).toEqual({ passed: true, attempts: 3 });
    expect(again.results()["trojkat"]).toBeUndefined();
  });
  test("uszkodzony zapis postępu jest ignorowany", () => {
    const storage = new MemoryStorage();
    storage.setItem("logomocja:progress", "{oops");
    expect(new ChallengeBook(storage).results()).toEqual({});
  });
  test("wyniki odpowiadają temu, co robi interpreter: cel zadania to rysunek programu wzorcowego", () => {
    const { book: b } = book();
    const c = CHALLENGES.find((x) => x.id === "trojkat")!;
    expect(c.target()).toEqual(run(c.solution, c.mode).segments);
    expect(b.submit("trojkat", c.solution).passed).toBe(true);
  });
});
EOF
