import type { Segment, Vec3 } from "../lang";

export type Mismatch =
  | { kind: "empty" }
  | { kind: "too-long" }
  | { kind: "missing"; at: Vec3 }
  | { kind: "extra"; at: Vec3 };

const length = (s: Segment) => Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
const total = (segs: Segment[]) => segs.reduce((n, s) => n + length(s), 0);

function distanceToSegment(p: Vec3, s: Segment): number {
  const [ax, ay, az] = s.from;
  const dx = s.to[0] - ax, dy = s.to[1] - ay, dz = s.to[2] - az;
  const len2 = dx * dx + dy * dy + dz * dz;
  let t = len2 === 0 ? 0 : ((p[0] - ax) * dx + (p[1] - ay) * dy + (p[2] - az) * dz) / len2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p[0] - (ax + t * dx), p[1] - (ay + t * dy), p[2] - (az + t * dz));
}

/** Points along a segment at most `step` apart (endpoints included). */
function* samples(s: Segment, step: number): Generator<Vec3> {
  const n = Math.min(2000, Math.max(1, Math.ceil(length(s) / step)));
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    yield [s.from[0] + (s.to[0] - s.from[0]) * t, s.from[1] + (s.to[1] - s.from[1]) * t, s.from[2] + (s.to[2] - s.from[2]) * t];
  }
}

/** Spatial hash of segments so that "is this point near any of them" does not scan every segment. */
class Index {
  private cells = new Map<string, Segment[]>();
  constructor(segs: Segment[], private cell: number) {
    for (const s of segs) {
      const seen = new Set<string>();
      for (const p of samples(s, cell / 2)) {
        const key = this.key(p);
        if (!seen.has(key)) {
          seen.add(key);
          (this.cells.get(key) ?? this.cells.set(key, []).get(key)!).push(s);
        }
      }
    }
  }
  private key(p: Vec3, d: Vec3 = [0, 0, 0]): string {
    return `${Math.floor(p[0] / this.cell) + d[0]},${Math.floor(p[1] / this.cell) + d[1]},${Math.floor(p[2] / this.cell) + d[2]}`;
  }
  near(p: Vec3, tol: number): boolean {
    for (let x = -1; x <= 1; x++)
      for (let y = -1; y <= 1; y++)
        for (let z = -1; z <= 1; z++) {
          const list = this.cells.get(this.key(p, [x, y, z]));
          if (list && list.some((s) => distanceToSegment(p, s) <= tol)) return true;
        }
    return false;
  }
}

/** First point of `a` that is farther than `tol` from every segment of `b`, if any. */
function uncovered(a: Segment[], b: Segment[], tol: number): Vec3 | null {
  const index = new Index(b, Math.max(tol * 4, 1));
  for (const s of a) for (const p of samples(s, tol)) if (!index.near(p, tol)) return p;
  return null;
}

/**
 * Compares two drawings as sets of geometric strokes: every part of `expected` must lie within `tol` of
 * `actual` and vice versa. Colour, width, drawing order and how strokes are split into segments do not matter.
 */
export function compareDrawings(expected: Segment[], actual: Segment[], tol: number): Mismatch | null {
  if (actual.length === 0) return { kind: "empty" };
  if (total(actual) > 3 * total(expected) + 20 * tol) return { kind: "too-long" };
  const missing = uncovered(expected, actual, tol);
  if (missing) return { kind: "missing", at: missing };
  const extra = uncovered(actual, expected, tol);
  if (extra) return { kind: "extra", at: extra };
  return null;
}
