export const getChallenge = (id: string): Challenge | undefined => CHALLENGES.find((c) => c.id === id);

export interface Verdict {
  passed: boolean;
  reason: string;
  error?: LogoError;
  /** Where the drawing first disagrees with the target, when it does. */
  at?: Vec3;
}

export interface ChallengeResult {
  passed: boolean;
  attempts: number;
}

const fmt = (p: Vec3, mode: Mode) =>
  "(" + (mode === "3d" ? p : p.slice(0, 2)).map((v) => String(Math.round(v * 10) / 10)).join(", ") + ")";

export function judge(challenge: Challenge, source: string): Verdict {
  const { segments, error } = run(source, challenge.mode);
  if (error) {
    return {
      passed: false,
      error,
      reason: `Program zawiera błąd (wiersz ${error.line}, kolumna ${error.column}): ${error.message}`,
    };
  }
  if (challenge.color && segments.some((s) => s.color !== challenge.color)) {
    return { passed: false, reason: `Zadanie wymaga, by wszystko było narysowane kolorem ${challenge.color} – znaleziono inny kolor.` };
  }
  const mismatch = compareDrawings(challenge.target(), segments, challenge.tolerance);
  if (!mismatch) return { passed: true, reason: "Zgadza się! Rysunek pasuje do wzoru." };
  switch (mismatch.kind) {
    case "empty":
      return { passed: false, reason: "Program zakończył się, ale nic nie narysowano." };
    case "too-long":
      return { passed: false, reason: "Rysunek jest znacznie dłuższy niż oczekiwany – jest w nim za dużo nadmiarowych linii." };
    case "missing":
      return { passed: false, at: mismatch.at, reason: `Brakuje fragmentu rysunku w okolicy punktu ${fmt(mismatch.at, challenge.mode)}.` };
    case "extra":
      return { passed: false, at: mismatch.at, reason: `Rysunek ma nadmiarowy fragment w okolicy punktu ${fmt(mismatch.at, challenge.mode)}.` };
  }
}

/** Judges submissions and remembers, across sessions, which challenges were solved. */
export class ChallengeBook {
  private store: SafeStore;
  private progress: Record<string, ChallengeResult> = {};

  constructor(storage: KeyValueStore) {
    this.store = safeStore(storage);
    try {
      const raw = JSON.parse(this.store.get("progress") ?? "{}");
      for (const [id, r] of Object.entries(raw as Record<string, ChallengeResult>)) {
        if (r && typeof r.passed === "boolean" && Number.isInteger(r.attempts)) this.progress[id] = { passed: r.passed, attempts: r.attempts };
      }
    } catch {
      this.progress = {};
    }
  }

  results(): Record<string, ChallengeResult> {
    return { ...this.progress };
  }

  submit(id: string, source: string): Verdict {
    const challenge = getChallenge(id);
    if (!challenge) throw new Error(`Nieznane zadanie: ${id}`);
    const verdict = judge(challenge, source);
    const before = this.progress[id] ?? { passed: false, attempts: 0 };
    this.progress[id] = { passed: before.passed || verdict.passed, attempts: before.attempts + 1 };
    this.store.set("progress", JSON.stringify(this.progress));
    return verdict;
  }
}
