import { describe, expect, test } from "bun:test";
import { highlight } from "../src/lang/highlight";

const kinds = (src: string) => highlight(src).map((s) => [src.slice(s.start, s.end), s.kind]);

describe("podświetlanie składni", () => {
  test("polecenia, liczby, teksty, nawiasy, operatory i komentarze mają osobne klasy", () => {
    expect(kinds('powtorz 4 [np 12.5 + .5] ; koniec\nkolor "#16866a"')).toEqual([
      ["powtorz", "command"], ["4", "number"], ["[", "bracket"], ["np", "command"], ["12.5", "number"],
      ["+", "operator"], [".5", "number"], ["]", "bracket"], ["; koniec", "comment"],
      ["kolor", "command"], ['"#16866a"', "string"],
    ]);
  });
  test("słowa kluczowe procedur, nrpowt, zmienne i nazwy procedur", () => {
    const src = "oto kw ma: bok\n np :bok * nrpowt\njuż\nkw 5";
    expect(kinds(src)).toEqual([
      ["oto", "keyword"], ["kw", "procedure"], ["ma:", "keyword"], ["bok", "name"],
      ["np", "command"], [":bok", "name"], ["*", "operator"], ["nrpowt", "keyword"],
      ["już", "keyword"], ["kw", "procedure"], ["5", "number"],
    ]);
  });
  test("polskie znaki, wielkie litery i zła liczba (1e3) nie rozbijają słów", () => {
    expect(kinds("NAPRZÓD 1e3")).toEqual([["NAPRZÓD", "command"], ["1e3", "error"]]);
    expect(kinds("jeśli 1 <= 2 [] ")).toEqual([["jeśli", "command"], ["1", "number"], ["<=", "operator"], ["2", "number"], ["[", "bracket"], ["]", "bracket"]]);
  });
  test("pokrywa dokładnie to, co było w źródle, i nie gubi pozycji", () => {
    const src = "np 10 ; x\n  pw 90";
    for (const s of highlight(src)) expect(src.slice(s.start, s.end)).toBe(src.slice(s.start, s.end).trim());
    expect(highlight(src).at(-1)).toEqual({ start: 15, end: 17, kind: "command" } as any);
  });
});
