import { COMMAND_BY_WORD, normalizeWord } from "./commands";

export type SpanKind = "comment" | "command" | "keyword" | "procedure" | "name" | "number" | "string" | "bracket" | "operator" | "error";

export interface Span {
  start: number;
  end: number;
  kind: SpanKind;
}

const KEYWORDS = new Set(["oto", "to", "już", "juz", "end", "nrpowt", "repcount"]);
const TOKEN = /(;[^\n]*)|("[^"\n]*"?)|(\d[\p{L}\p{M}\p{N}_.]*|\.\d[\p{L}\p{M}\p{N}_.]*)|(:[\p{L}][\p{L}\p{M}\p{N}_]*)|([\p{L}][\p{L}\p{M}\p{N}_]*)|(<=|>=|<>|[<>=+\-*/,:])|([[\]()])/gu;

/** Splits source into coloured spans for the editor overlay; whitespace is not covered. */
export function highlight(source: string): Span[] {
  const procs = new Set<string>();
  for (const m of source.matchAll(/^[ \t]*(?:oto|to)[ \t]+([\p{L}][\p{L}\p{M}\p{N}_]*)/gimu)) procs.add(normalizeWord(m[1]));

  const spans: Span[] = [];
  for (const m of source.matchAll(TOKEN)) {
    const start = m.index!;
    const end = start + m[0].length;
    let kind: SpanKind;
    if (m[1]) kind = "comment";
    else if (m[2]) kind = /^"#[0-9a-fA-F]{6}"$/.test(m[2]) ? "string" : "error";
    else if (m[3]) kind = /^(\d+(\.\d+)?|\.\d+)$/.test(m[3]) ? "number" : "error";
    else if (m[4]) kind = "name";
    else if (m[5]) {
      const w = normalizeWord(m[5]);
      if (w === "ma" && source[end] === ":") {
        spans.push({ start, end: end + 1, kind: "keyword" });
        continue;
      }
      kind = KEYWORDS.has(w) ? "keyword" : COMMAND_BY_WORD.has(w) ? "command" : procs.has(w) ? "procedure" : "name";
    } else if (m[6]) kind = "operator";
    else kind = "bracket";
    spans.push({ start, end, kind });
  }
  return spans;
}
EOF
