// Builds the static site into dist/. BASE_PATH (default "/") is where the site will be served from.
import { cp, mkdir, rm } from "node:fs/promises";
import { createHash } from "node:crypto";

const rawBase = process.env.BASE_PATH?.trim() || "/";
const base = (rawBase.startsWith("/") ? rawBase : "/" + rawBase).replace(/\/*$/, "/");
const watch = process.argv.includes("--watch");

async function build() {
  await rm("dist", { recursive: true, force: true });
  await mkdir("dist/assets", { recursive: true });

  const result = await Bun.build({
    entrypoints: ["src/main.ts"],
    outdir: "dist/assets",
    target: "browser",
    format: "esm",
    minify: !watch,
    sourcemap: watch ? "inline" : "none",
    naming: "app-[hash].[ext]",
    loader: { ".logo": "text" },
    define: { "process.env.NODE_ENV": '"production"', __BASE_PATH__: JSON.stringify(base) },
  });
  if (!result.success) {
    for (const log of result.logs) console.error(log);
    process.exit(1);
  }
  const js = result.outputs.find((o) => o.path.endsWith(".js"))!;
  const jsName = js.path.split("/").pop()!;

  const css = await Bun.file("src/styles.css").text();
  const cssName = `style-${createHash("sha1").update(css).digest("hex").slice(0, 8)}.css`;
  await Bun.write(`dist/assets/${cssName}`, css);

  // Asset URLs are relative, so the site works from any sub-path; BASE_PATH is used for the manifest scope.
