export type ThemeChoice = "auto" | "light" | "dark";
export type EffectiveTheme = "light" | "dark";

const KEY = "logomocja:theme";
const media = window.matchMedia?.("(prefers-color-scheme: dark)");

export function savedTheme(): ThemeChoice {
  try {
    const t = localStorage.getItem(KEY);
    return t === "light" || t === "dark" ? t : "auto";
  } catch {
    return "auto";
  }
}

export function effectiveTheme(): EffectiveTheme {
  const forced = document.documentElement.dataset.theme;
  if (forced === "light" || forced === "dark") return forced;
  return media?.matches ? "dark" : "light";
}

export function applyTheme(choice: ThemeChoice): void {
  if (choice === "auto") delete document.documentElement.dataset.theme;
  else document.documentElement.dataset.theme = choice;
  try {
    if (choice === "auto") localStorage.removeItem(KEY);
    else localStorage.setItem(KEY, choice);
  } catch {
    /* ignore */
  }
  window.dispatchEvent(new Event("logomocja-theme"));
}

media?.addEventListener?.("change", () => window.dispatchEvent(new Event("logomocja-theme")));

/** Colours read from the stylesheet so canvases follow the theme. */
export function palette() {
  const css = getComputedStyle(document.documentElement);
  const v = (name: string) => css.getPropertyValue(name).trim();
  return {
    paper: v("--paper"), grid: v("--grid"), gridMajor: v("--grid-major"), axis: v("--axis"), label: v("--canvas-label"),
    accent: v("--accent"), ink: v("--ink"), ghost: v("--ghost"),
    axisX: v("--axis-x"), axisY: v("--axis-y"), axisZ: v("--axis-z"),
  };
}

/** Dark colours chosen for a light sheet would vanish on the dark canvas; lift them a little (display only). */
export function displayColor(hex: string, theme: EffectiveTheme): string {
  if (theme === "light") return hex;
  const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
  const lum = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
  if (lum > 0.38) return hex;
  const k = (0.38 - lum) / (1 - lum) * 1.15;
  const mix = (c: number) => Math.round(c + (255 - c) * Math.min(1, k));
  return `rgb(${mix(r)},${mix(g)},${mix(b)})`;
}
