import type { Segment } from "../lang";
import type { TurtleView } from "../core/workspace";
import { h } from "./dom";
import { displayColor, effectiveTheme, palette } from "./theme";

interface Bounds { minX: number; maxX: number; minY: number; maxY: number }

const MIN_SCALE = 0.01;
const MAX_SCALE = 400;

/** Nice grid step (1, 2, 5 × 10^n) that is at least `target` units. */
export function niceStep(target: number): number {
  const pow = Math.pow(10, Math.floor(Math.log10(target)));
  for (const m of [1, 2, 5, 10]) if (m * pow >= target) return m * pow;
  return 10 * pow;
}

export function boundsOf(segments: Segment[], turtle: TurtleView | null): Bounds {
  const b: Bounds = { minX: 0, maxX: 0, minY: 0, maxY: 0 }; // the origin is always part of the picture
  const add = (x: number, y: number) => {
    if (x < b.minX) b.minX = x;
    if (x > b.maxX) b.maxX = x;
    if (y < b.minY) b.minY = y;
    if (y > b.maxY) b.maxY = y;
  };
  for (const s of segments) {
    add(s.from[0], s.from[1]);
    add(s.to[0], s.to[1]);
  }
  if (turtle) add(turtle.pos[0], turtle.pos[1]);
  return b;
}

export class View2D {
  readonly el: HTMLElement;
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private segments: Segment[] = [];
  private ghost: Segment[] | null = null;
  private turtle: TurtleView | null = null;
  // View: world point (cx, cy) sits at the canvas centre; `scale` is pixels per unit (y points up).
  private cx = 0;
  private cy = 0;
  private scale = 1;
  private target: { cx: number; cy: number; scale: number } | null = null;
  private autoFit = true;
  private dirty = true;
  private raf = 0;
  private width = 0;
  private height = 0;
  private dpr = 1;
  private pointers = new Map<number, { x: number; y: number }>();
  private lastPinch: { dist: number; x: number; y: number } | null = null;
  private resizeObserver: ResizeObserver;
  private onTheme = () => this.invalidate();

  constructor() {
    this.canvas = h("canvas", { class: "view-canvas", tabindex: 0, role: "img", "aria-label": "Rysunek żółwia, widok 2D" });
    this.ctx = this.canvas.getContext("2d")!;
    this.el = h("div", { class: "view2d" }, this.canvas);
    this.canvas.addEventListener("pointerdown", (e) => this.pointerDown(e));
    this.canvas.addEventListener("pointermove", (e) => this.pointerMove(e));
    this.canvas.addEventListener("pointerup", (e) => this.pointerUp(e));
    this.canvas.addEventListener("pointercancel", (e) => this.pointerUp(e));
    this.canvas.addEventListener("wheel", (e) => this.wheel(e), { passive: false });
    this.canvas.addEventListener("dblclick", () => this.fit());
    this.canvas.addEventListener("keydown", (e) => this.key(e));
    window.addEventListener("logomocja-theme", this.onTheme);
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(this.el);
  }

  destroy(): void {
    window.removeEventListener("logomocja-theme", this.onTheme);
    this.resizeObserver.disconnect();
    cancelAnimationFrame(this.raf);
  }

  setSegments(segments: Segment[]): void {
    this.segments = segments;
    this.canvas.setAttribute("aria-label", `Rysunek żółwia, widok 2D: ${segments.length} ${segments.length === 1 ? "odcinek" : "odcinków"}`);
    this.refit();
    this.invalidate();
  }

  setTurtle(turtle: TurtleView | null): void {
    this.turtle = turtle;
    this.invalidate();
  }

  setGhost(ghost: Segment[] | null): void {
    this.ghost = ghost;
    this.refit();
    this.invalidate();
  }

  get segmentCount(): number {
    return this.segments.length;
  }

  /** Shows the whole drawing; `snap` skips the easing animation. */
  fit(snap = false): void {
    this.autoFit = true;
    this.refit(snap);
    this.invalidate();
  }

  private refit(snap = false): void {
    if (!this.autoFit || !this.width) return;
    const all = this.ghost ? [...this.segments, ...this.ghost] : this.segments;
    const b = boundsOf(all, this.turtle);
    const empty = all.length === 0;
    const w = empty ? 300 : b.maxX - b.minX, hgt = empty ? 300 : b.maxY - b.minY;
    const pad = 28;
    const avail = Math.max(40, Math.min(this.width, this.height) - 2 * pad);
    const sx = (this.width - 2 * pad) / Math.max(w, 1e-6);
    const sy = (this.height - 2 * pad) / Math.max(hgt, 1e-6);
    const scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, Math.min(sx, sy, avail / 4)));
    const t = {
      cx: empty ? 0 : (b.minX + b.maxX) / 2,
      cy: empty ? 0 : (b.minY + b.maxY) / 2,
      scale: Math.min(scale, Math.max(sx, 0) === 0 ? scale : scale),
    };
    if (snap) {
      Object.assign(this, t);
      this.target = null;
    } else {
      this.target = t;
    }
  }

  private resize(): void {
    const rect = this.el.getBoundingClientRect();
    this.dpr = window.devicePixelRatio || 1;
    this.width = Math.max(1, Math.floor(rect.width));
    this.height = Math.max(1, Math.floor(rect.height));
    this.canvas.width = Math.floor(this.width * this.dpr);
    this.canvas.height = Math.floor(this.height * this.dpr);
    this.canvas.style.width = this.width + "px";
    this.canvas.style.height = this.height + "px";
    const first = this.scale === 1 && this.cx === 0 && this.cy === 0;
    this.refit(first);
    this.invalidate();
  }

  private invalidate(): void {
    this.dirty = true;
    if (!this.raf) this.raf = requestAnimationFrame(() => this.frame());
  }

  private frame(): void {
    this.raf = 0;
    if (this.target) {
      const t = this.target;
      const k = 0.28;
      this.cx += (t.cx - this.cx) * k;
      this.cy += (t.cy - this.cy) * k;
      this.scale *= Math.pow(t.scale / this.scale, k);
      if (Math.abs(t.cx - this.cx) * this.scale < 0.2 && Math.abs(t.cy - this.cy) * this.scale < 0.2 && Math.abs(t.scale / this.scale - 1) < 0.002) {
        Object.assign(this, t);
        this.target = null;
      } else {
        this.dirty = true;
      }
    }
    if (this.dirty) {
      this.dirty = false;
      this.draw();
    }
    if (this.dirty || this.target) this.raf = requestAnimationFrame(() => this.frame());
  }

  /** Called by the host when the container becomes visible again (size may have changed while hidden). */
  refresh(): void {
    this.resize();
  }

  private toScreen(x: number, y: number): [number, number] {
    return [this.width / 2 + (x - this.cx) * this.scale, this.height / 2 - (y - this.cy) * this.scale];
  }

  private draw(): void {
    const ctx = this.ctx;
    const pal = palette();
    const theme = effectiveTheme();
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.fillStyle = pal.paper;
    ctx.fillRect(0, 0, this.width, this.height);
    this.drawGrid(ctx, pal);
    if (this.ghost) this.drawSegments(ctx, this.ghost, pal.ghost, 7, theme, true);
    this.drawSegments(ctx, this.segments, null, 0, theme, false);
    this.drawOrigin(ctx, pal);
    if (this.turtle) this.drawTurtle(ctx, this.turtle, pal, theme);
  }

  private drawGrid(ctx: CanvasRenderingContext2D, pal: ReturnType<typeof palette>): void {
    const step = niceStep(28 / this.scale);
    const major = step * 5;
    const x0 = this.cx - this.width / 2 / this.scale, x1 = this.cx + this.width / 2 / this.scale;
    const y0 = this.cy - this.height / 2 / this.scale, y1 = this.cy + this.height / 2 / this.scale;
    ctx.lineWidth = 1;
    for (const pass of [0, 1]) {
      ctx.strokeStyle = pass === 0 ? pal.grid : pal.gridMajor;
      ctx.beginPath();
      for (let x = Math.floor(x0 / step) * step; x <= x1; x += step) {
        const isMajor = Math.abs(x / major - Math.round(x / major)) < 1e-9;
        if (isMajor !== (pass === 1)) continue;
        const [sx] = this.toScreen(x, 0);
        ctx.moveTo(Math.round(sx) + 0.5, 0);
        ctx.lineTo(Math.round(sx) + 0.5, this.height);
      }
      for (let y = Math.floor(y0 / step) * step; y <= y1; y += step) {
        const isMajor = Math.abs(y / major - Math.round(y / major)) < 1e-9;
        if (isMajor !== (pass === 1)) continue;
        const [, sy] = this.toScreen(0, y);
        ctx.moveTo(0, Math.round(sy) + 0.5);
        ctx.lineTo(this.width, Math.round(sy) + 0.5);
      }
      ctx.stroke();
    }
    // axes and their labels
    const [ox, oy] = this.toScreen(0, 0);
    ctx.strokeStyle = pal.axis;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(0, oy);
    ctx.lineTo(this.width, oy);
    ctx.moveTo(ox, 0);
    ctx.lineTo(ox, this.height);
    ctx.stroke();
    ctx.fillStyle = pal.label;
    ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
    ctx.textBaseline = "top";
    ctx.textAlign = "center";
    const labelY = Math.min(Math.max(oy + 4, 2), this.height - 14);
    for (let x = Math.ceil(x0 / major) * major; x <= x1; x += major) {
      if (Math.abs(x) < 1e-9) continue;
      const [sx] = this.toScreen(x, 0);
      ctx.fillText(formatTick(x), sx, labelY);
    }
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const labelX = Math.min(Math.max(ox + 5, 2), this.width - 40);
    for (let y = Math.ceil(y0 / major) * major; y <= y1; y += major) {
      if (Math.abs(y) < 1e-9) continue;
      const [, sy] = this.toScreen(0, y);
      ctx.fillText(formatTick(y), labelX, sy - 7);
    }
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
  }

  private drawSegments(ctx: CanvasRenderingContext2D, segs: Segment[], override: string | null, widthOverride: number, theme: "light" | "dark", dashed: boolean): void {
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    if (dashed) ctx.globalAlpha = 0.5;
    let key = "";
    let open = false;
    for (const s of segs) {
      const k = override ? "g" : s.color + s.width;
      if (k !== key) {
        if (open) ctx.stroke();
        ctx.beginPath();
        open = true;
        key = k;
        ctx.strokeStyle = override ?? displayColor(s.color, theme);
        ctx.lineWidth = widthOverride || s.width;
      }
      const [ax, ay] = this.toScreen(s.from[0], s.from[1]);
      const [bx, by] = this.toScreen(s.to[0], s.to[1]);
      ctx.moveTo(ax, ay);
      ctx.lineTo(bx, by);
    }
