    ctx.fillStyle = pal.paper;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(ox, oy, 4.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = pal.label;
    ctx.font = "600 11px ui-sans-serif, system-ui, sans-serif";
    ctx.textAlign = "left";
    ctx.fillText("0", ox + 8, oy + 15);
  }

  private drawTurtle(ctx: CanvasRenderingContext2D, t: TurtleView, pal: ReturnType<typeof palette>, theme: "light" | "dark"): void {
    const [x, y] = this.toScreen(t.pos[0], t.pos[1]);
    // heading on screen: x to the right, y up on the page → down on the screen
    const ang = Math.atan2(-t.heading[1], t.heading[0]);
    const color = displayColor(t.color, theme);
