    ctx.lineCap = "round";
    ctx.strokeStyle = color;
    ctx.lineWidth = 4;
    ctx.beginPath();
    for (const [lx, ly] of [[-8, -6], [8, -6], [-8, 7], [8, 7]]) {
      ctx.moveTo(lx * 0.6, ly * 0.6);
      ctx.lineTo(lx * 1.25, ly * 1.2);
    }
    ctx.stroke();
    // head
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(0, -14, 4.5, 0, Math.PI * 2);
    ctx.fill();
    // shell
    ctx.beginPath();
    ctx.ellipse(0, 1, 9, 12, 0, 0, Math.PI * 2);
    ctx.fillStyle = t.penDown ? color : pal.paper;
    ctx.fill();
    ctx.lineWidth = 2.5;
    ctx.strokeStyle = pal.paper;
    ctx.stroke();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = t.penDown ? pal.paper : color;
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(0, 10);
    ctx.moveTo(-6, 1);
    ctx.lineTo(6, 1);
    ctx.stroke();
    ctx.restore();
  }

  // --- interaction -------------------------------------------------------------------------------------------

  private userMoved(): void {
    this.autoFit = false;
    this.target = null;
    this.invalidate();
  }

  private pointerDown(e: PointerEvent): void {
    this.canvas.setPointerCapture(e.pointerId);
    this.pointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
    this.lastPinch = null;
    this.canvas.classList.add("grabbing");
  }

  private pointerMove(e: PointerEvent): void {
    const p = this.pointers.get(e.pointerId);
    if (!p) return;
    const nx = e.offsetX, ny = e.offsetY;
    if (this.pointers.size === 1) {
      this.cx -= (nx - p.x) / this.scale;
      this.cy += (ny - p.y) / this.scale;
      this.userMoved();
    }
    p.x = nx;
    p.y = ny;
    if (this.pointers.size === 2) {
      const [a, b] = [...this.pointers.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
      if (this.lastPinch) {
        this.zoomAt(mx, my, dist / this.lastPinch.dist);
        this.cx -= (mx - this.lastPinch.x) / this.scale;
        this.cy += (my - this.lastPinch.y) / this.scale;
      }
      this.lastPinch = { dist, x: mx, y: my };
      this.userMoved();
    }
  }

  private pointerUp(e: PointerEvent): void {
    this.pointers.delete(e.pointerId);
    this.lastPinch = null;
    if (!this.pointers.size) this.canvas.classList.remove("grabbing");
  }

  private zoomAt(sx: number, sy: number, factor: number): void {
    const wx = this.cx + (sx - this.width / 2) / this.scale;
    const wy = this.cy - (sy - this.height / 2) / this.scale;
    this.scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, this.scale * factor));
    this.cx = wx - (sx - this.width / 2) / this.scale;
    this.cy = wy + (sy - this.height / 2) / this.scale;
  }

  private wheel(e: WheelEvent): void {
    e.preventDefault();
    this.zoomAt(e.offsetX, e.offsetY, Math.exp(-e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0015)));
    this.userMoved();
  }

  private key(e: KeyboardEvent): void {
    const step = 40 / this.scale;
    switch (e.key) {
      case "ArrowLeft": this.cx -= step; break;
      case "ArrowRight": this.cx += step; break;
      case "ArrowUp": this.cy += step; break;
      case "ArrowDown": this.cy -= step; break;
      case "+": case "=": this.zoomAt(this.width / 2, this.height / 2, 1.25); break;
      case "-": case "_": this.zoomAt(this.width / 2, this.height / 2, 0.8); break;
      case "0": this.fit(); return;
      default: return;
    }
    e.preventDefault();
    this.userMoved();
  }

  zoomBy(factor: number): void {
    this.zoomAt(this.width / 2, this.height / 2, factor);
    this.userMoved();
  }

  // --- export ------------------------------------------------------------------------------------------------

  /** PNG of the drawing on a light sheet, fitted with a margin (independent of the current pan and zoom). */
  exportPNG(): Promise<Blob> {
    const b = boundsOf(this.segments, null);
    const empty = this.segments.length === 0;
    const w = empty ? 300 : b.maxX - b.minX, hgt = empty ? 300 : b.maxY - b.minY;
    const longest = Math.max(w, hgt, 1e-6);
    const px = 1600;
    const margin = 80;
    const scale = (px - 2 * margin) / longest;
    const W = Math.max(400, Math.round(w * scale + 2 * margin)), H = Math.max(400, Math.round(hgt * scale + 2 * margin));
    const canvas = h("canvas") as HTMLCanvasElement;
    canvas.width = W;
    canvas.height = H;
    const ctx = canvas.getContext("2d")!;
    ctx.fillStyle = "#fffdf6";
    ctx.fillRect(0, 0, W, H);
    const cx = (b.minX + b.maxX) / 2, cy = (b.minY + b.maxY) / 2;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    const lw = Math.max(1, scale > 4 ? 1 : 1) * Math.max(1, W / 800);
    for (const s of this.segments) {
      ctx.strokeStyle = s.color;
      ctx.lineWidth = s.width * lw;
      ctx.beginPath();
      ctx.moveTo(W / 2 + (s.from[0] - cx) * scale, H / 2 - (s.from[1] - cy) * scale);
      ctx.lineTo(W / 2 + (s.to[0] - cx) * scale, H / 2 - (s.to[1] - cy) * scale);
      ctx.stroke();
    }
    return new Promise((resolve, reject) => canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error("PNG"))), "image/png"));
  }
}

function formatTick(v: number): string {
  const abs = Math.abs(v);
  if (abs >= 1e6) return v / 1e6 + "M";
  if (abs >= 1e4) return v / 1e3 + "k";
  return String(Math.round(v * 1000) / 1000);
}
