}

interface Batch {
  data: Float32Array;
  count: number; // vertices
  buffer: WebGLBuffer | null;
  uploaded: number; // floats already on the GPU
  capacity: number; // floats allocated on the GPU
}

const newBatch = (): Batch => ({ data: new Float32Array(FLOATS_PER_VERTEX * 6 * 256), count: 0, buffer: null, uploaded: 0, capacity: 0 });

export class View3D {
  readonly el: HTMLElement;
  private canvas: HTMLCanvasElement;
  private gl!: WebGLRenderingContext;
  private program!: WebGLProgram;
  private loc!: Record<string, number>;
  private uni!: Record<string, WebGLUniformLocation | null>;
  private drawing = newBatch();
  private ghostBatch = newBatch();
  private deco = newBatch(); // grid + axes
  private marker = newBatch();
  private decoKey = "";
  private segments: Segment[] = [];
  private ghost: Segment[] | null = null;
  private turtle: TurtleView | null = null;
  private labels: Record<"x" | "y" | "z", HTMLElement>;
  // Orbit camera around `target`; Z is up.
  private target: V3 = [0, 0, 0];
  private dist = 400;
  private yaw = DEFAULT_YAW;
  private pitch = DEFAULT_PITCH;
  private goal: { target: V3; dist: number } | null = null;
  private autoFit = true;
  private radius = 100;
  private width = 1;
  private height = 1;
  private dpr = 1;
  private dirty = true;
  private raf = 0;
  private vp: Mat4 = new Float32Array(16);
  private pointers = new Map<number, { x: number; y: number; button: number }>();
  private lastPinch: { dist: number; x: number; y: number } | null = null;
  private resizeObserver: ResizeObserver;
  private onTheme = () => this.invalidate();

  constructor() {
    this.canvas = h("canvas", { class: "view-canvas", tabindex: 0, role: "img", "aria-label": "Rysunek żółwia, widok 3D" });
    this.labels = {
      x: h("span", { class: "axis-label axis-x", "aria-hidden": "true" }, "X"),
      y: h("span", { class: "axis-label axis-y", "aria-hidden": "true" }, "Y"),
      z: h("span", { class: "axis-label axis-z", "aria-hidden": "true" }, "Z"),
    };
    this.el = h("div", { class: "view3d" }, this.canvas, this.labels.x, this.labels.y, this.labels.z);
    this.initGL();
    const c = this.canvas;
    c.addEventListener("pointerdown", (e) => this.pointerDown(e));
    c.addEventListener("pointermove", (e) => this.pointerMove(e));
    c.addEventListener("pointerup", (e) => this.pointerUp(e));
    c.addEventListener("pointercancel", (e) => this.pointerUp(e));
    c.addEventListener("wheel", (e) => this.wheel(e), { passive: false });
    c.addEventListener("contextmenu", (e) => e.preventDefault());
    c.addEventListener("dblclick", () => this.resetView());
    c.addEventListener("keydown", (e) => this.key(e));
    c.addEventListener("webglcontextlost", (e) => e.preventDefault());
    c.addEventListener("webglcontextrestored", () => {
