  // --- GL setup ----------------------------------------------------------------------------------------------

  private initGL(): void {
    const gl = (this.canvas.getContext("webgl", { antialias: true, alpha: false, preserveDrawingBuffer: true }) ||
      this.canvas.getContext("experimental-webgl")) as WebGLRenderingContext | null;
