import type { Segment } from "../lang";
import type { TurtleView } from "../core/workspace";
import { h } from "./dom";
import { add, cross, lookAt, multiply, norm, perspective, project, scale as vscale, sub, type Mat4, type V3 } from "./mat4";
import { displayColor, effectiveTheme, palette } from "./theme";
import { niceStep } from "./view2d";

const VERT = `
attribute vec3 aA;
attribute vec3 aB;
attribute vec2 aCorner;
attribute vec4 aColor;
attribute float aWidth;
uniform mat4 uVP;
uniform vec2 uViewport;
uniform vec2 uDepth;
varying vec4 vColor;
varying float vFade;
void main() {
  vec4 pa = uVP * vec4(aA, 1.0);
  vec4 pb = uVP * vec4(aB, 1.0);
  float n = 0.05;
  if (pa.w < n && pb.w < n) { gl_Position = vec4(2.0, 2.0, 2.0, 1.0); vColor = aColor; vFade = 0.0; return; }
  if (pa.w < n) pa = mix(pa, pb, (n - pa.w) / (pb.w - pa.w));
  else if (pb.w < n) pb = mix(pb, pa, (n - pb.w) / (pa.w - pb.w));
  vec2 sa = pa.xy / pa.w * 0.5 * uViewport;
  vec2 sb = pb.xy / pb.w * 0.5 * uViewport;
  vec2 d = sb - sa;
  float len = length(d);
  vec2 dir = len > 0.0001 ? d / len : vec2(1.0, 0.0);
  vec2 nrm = vec2(-dir.y, dir.x);
  vec4 p = mix(pa, pb, aCorner.x);
  vec2 s = mix(sa, sb, aCorner.x);
  float hw = aWidth * 0.5;
  s += dir * (aCorner.x * 2.0 - 1.0) * hw + nrm * aCorner.y * hw;
  gl_Position = vec4(s / (0.5 * uViewport) * p.w, p.z, p.w);
  vColor = aColor;
  vFade = clamp((p.w - (uDepth.x - uDepth.y)) / (2.0 * uDepth.y), 0.0, 1.0);
}`;

const FRAG = `
precision mediump float;
uniform vec3 uFog;
uniform float uFogAmount;
varying vec4 vColor;
varying float vFade;
void main() {
  gl_FragColor = vec4(mix(vColor.rgb, uFog, vFade * uFogAmount), vColor.a);
}`;

const FLOATS_PER_VERTEX = 13; // A(3) B(3) corner(2) color(4) width(1)
const FOV = (40 * Math.PI) / 180;
const DEFAULT_YAW = (28 * Math.PI) / 180;
const DEFAULT_PITCH = (24 * Math.PI) / 180;

export interface WebGLSupport {
  ok: boolean;
  reason: string;
}

let supportCache: WebGLSupport | null = null;

/** Whether a WebGL context can be created here; the reason (Polish) is shown when it cannot. */
export function webglSupport(): WebGLSupport {
  if (supportCache) return supportCache;
  try {
    const canvas = document.createElement("canvas");
    const gl = (canvas.getContext("webgl", { failIfMajorPerformanceCaveat: false }) ||
      canvas.getContext("experimental-webgl")) as WebGLRenderingContext | null;
    if (!gl) {
      supportCache = {
        ok: false,
        reason: "Ta przeglądarka lub to urządzenie nie udostępnia WebGL (przyspieszanej grafiki), a bez niego widok 3D nie działa. Tryb 2D działa normalnie.",
      };
    } else {
      supportCache = { ok: true, reason: "" };
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    }
  } catch {
    supportCache = { ok: false, reason: "Nie udało się uruchomić WebGL w tej przeglądarce, więc widok 3D jest wyłączony. Tryb 2D działa normalnie." };
  }
  return supportCache;
}

export function parseCssColor(css: string): [number, number, number, number] {
  const s = css.trim();
  let m = /^#([0-9a-f]{6})$/i.exec(s);
  if (m) return [parseInt(m[1].slice(0, 2), 16) / 255, parseInt(m[1].slice(2, 4), 16) / 255, parseInt(m[1].slice(4, 6), 16) / 255, 1];
  m = /^#([0-9a-f])([0-9a-f])([0-9a-f])$/i.exec(s);
  if (m) return [parseInt(m[1] + m[1], 16) / 255, parseInt(m[2] + m[2], 16) / 255, parseInt(m[3] + m[3], 16) / 255, 1];
  m = /^rgba?\(\s*([\d.]+)[ ,]+([\d.]+)[ ,]+([\d.]+)(?:[ ,/]+([\d.]+))?\s*\)$/i.exec(s);
  if (m) return [Number(m[1]) / 255, Number(m[2]) / 255, Number(m[3]) / 255, m[4] === undefined ? 1 : Number(m[4])];
  return [0.5, 0.5, 0.5, 1];
}

interface Batch {
  data: Float32Array;
  count: number; // vertices
  buffer: WebGLBuffer | null;
  uploaded: number; // floats already on the GPU
  capacity: number; // floats allocated on the GPU
}

const newBatch = (): Batch => ({ data: new Float32Array(FLOATS_PER_VERTEX * 6 * 256), count: 0, buffer: null, uploaded: 0, capacity: 0 });

export class View3D {
  readonly el: HTMLElement;
  private canvas: HTMLCanvasElement;
  private gl!: WebGLRenderingContext;
  private program!: WebGLProgram;
  private loc!: Record<string, number>;
  private uni!: Record<string, WebGLUniformLocation | null>;
  private drawing = newBatch();
  private ghostBatch = newBatch();
  private deco = newBatch(); // grid + axes
  private marker = newBatch();
  private decoKey = "";
  private segments: Segment[] = [];
  private ghost: Segment[] | null = null;
  private turtle: TurtleView | null = null;
  private labels: Record<"x" | "y" | "z", HTMLElement>;
  // Orbit camera around `target`; Z is up.
  private target: V3 = [0, 0, 0];
  private dist = 400;
  private yaw = DEFAULT_YAW;
  private pitch = DEFAULT_PITCH;
  private goal: { target: V3; dist: number } | null = null;
  private autoFit = true;
  private radius = 100;
  private width = 1;
  private height = 1;
  private dpr = 1;
  private dirty = true;
  private raf = 0;
  private vp: Mat4 = new Float32Array(16);
  private pointers = new Map<number, { x: number; y: number; button: number }>();
  private lastPinch: { dist: number; x: number; y: number } | null = null;
  private resizeObserver: ResizeObserver;
  private onTheme = () => this.invalidate();

  constructor() {
    this.canvas = h("canvas", { class: "view-canvas", tabindex: 0, role: "img", "aria-label": "Rysunek żółwia, widok 3D" });
    this.labels = {
      x: h("span", { class: "axis-label axis-x", "aria-hidden": "true" }, "X"),
      y: h("span", { class: "axis-label axis-y", "aria-hidden": "true" }, "Y"),
      z: h("span", { class: "axis-label axis-z", "aria-hidden": "true" }, "Z"),
    };
    this.el = h("div", { class: "view3d" }, this.canvas, this.labels.x, this.labels.y, this.labels.z);
    this.initGL();
    const c = this.canvas;
    c.addEventListener("pointerdown", (e) => this.pointerDown(e));
    c.addEventListener("pointermove", (e) => this.pointerMove(e));
    c.addEventListener("pointerup", (e) => this.pointerUp(e));
    c.addEventListener("pointercancel", (e) => this.pointerUp(e));
    c.addEventListener("wheel", (e) => this.wheel(e), { passive: false });
    c.addEventListener("contextmenu", (e) => e.preventDefault());
    c.addEventListener("dblclick", () => this.resetView());
    c.addEventListener("keydown", (e) => this.key(e));
    c.addEventListener("webglcontextlost", (e) => e.preventDefault());
    c.addEventListener("webglcontextrestored", () => {
      this.initGL();
      this.rebuildAll();
    });
    window.addEventListener("logomocja-theme", this.onTheme);
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(this.el);
  }

  destroy(): void {
    window.removeEventListener("logomocja-theme", this.onTheme);
    this.resizeObserver.disconnect();
    cancelAnimationFrame(this.raf);
    this.gl.getExtension("WEBGL_lose_context")?.loseContext();
  }

  // --- GL setup ----------------------------------------------------------------------------------------------

  private initGL(): void {
    const gl = (this.canvas.getContext("webgl", { antialias: true, alpha: false, preserveDrawingBuffer: true }) ||
      this.canvas.getContext("experimental-webgl")) as WebGLRenderingContext | null;
    if (!gl) throw new Error("WebGL niedostępny");
    this.gl = gl;
    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) ?? "shader");
      return s;
    };
    const program = gl.createProgram()!;
    gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
    gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program) ?? "link");
    this.program = program;
    this.loc = {};
    for (const a of ["aA", "aB", "aCorner", "aColor", "aWidth"]) this.loc[a] = gl.getAttribLocation(program, a);
    this.uni = {};
    for (const u of ["uVP", "uViewport", "uDepth", "uFog", "uFogAmount"]) this.uni[u] = gl.getUniformLocation(program, u);
    for (const b of [this.drawing, this.ghostBatch, this.deco, this.marker]) {
      b.buffer = gl.createBuffer();
      b.uploaded = 0;
      b.capacity = 0;
    }
  }

  // --- geometry batches --------------------------------------------------------------------------------------

  private pushSegment(b: Batch, a: V3, bb: V3, color: [number, number, number, number], width: number): void {
    const need = (b.count + 6) * FLOATS_PER_VERTEX;
    if (need > b.data.length) {
      const bigger = new Float32Array(Math.max(need, b.data.length * 2));
      bigger.set(b.data);
      b.data = bigger;
    }
    const corners = [[0, -1], [1, -1], [1, 1], [0, -1], [1, 1], [0, 1]];
    let o = b.count * FLOATS_PER_VERTEX;
    for (const [cx, cy] of corners) {
      const d = b.data;
      d[o++] = a[0]; d[o++] = a[1]; d[o++] = a[2];
      d[o++] = bb[0]; d[o++] = bb[1]; d[o++] = bb[2];
      d[o++] = cx; d[o++] = cy;
      d[o++] = color[0]; d[o++] = color[1]; d[o++] = color[2]; d[o++] = color[3];
      d[o++] = width;
    }
    b.count += 6;
  }

  private colorFor(hex: string): [number, number, number, number] {
    return parseCssColor(displayColor(hex, effectiveTheme()));
  }

  private rebuildDrawing(batch: Batch, segs: Segment[], override: [number, number, number, number] | null, width: number): void {
    batch.count = 0;
    batch.uploaded = 0;
    for (const s of segs) this.pushSegment(batch, s.from, s.to, override ?? this.colorFor(s.color), width || s.width);
  }

  private rebuildAll(): void {
    this.rebuildDrawing(this.drawing, this.segments, null, 0);
    this.rebuildGhost();
    this.decoKey = "";
    this.invalidate();
  }

  private rebuildGhost(): void {
    this.ghostBatch.count = 0;
    this.ghostBatch.uploaded = 0;
    if (this.ghost) {
      const c = parseCssColor(palette().ghost);
      this.rebuildDrawing(this.ghostBatch, this.ghost, [c[0], c[1], c[2], 0.55], 6);
    }
  }

  setSegments(segments: Segment[]): void {
    const prev = this.segments;
    const appended = prev.length > 0 && segments.length > prev.length && segments[prev.length - 1] === prev[prev.length - 1] && segments[0] === prev[0];
    this.segments = segments;
    if (appended) {
      for (let i = prev.length; i < segments.length; i++) {
        const s = segments[i];
        this.pushSegment(this.drawing, s.from, s.to, this.colorFor(s.color), s.width);
      }
    } else if (prev.length !== segments.length || prev[0] !== segments[0] || prev[prev.length - 1] !== segments[segments.length - 1]) {
      this.rebuildDrawing(this.drawing, segments, null, 0);
    }
    this.canvas.setAttribute("aria-label", `Rysunek żółwia, widok 3D: ${segments.length} ${segments.length === 1 ? "odcinek" : "odcinków"}`);
    this.refit();
    this.invalidate();
  }

  setTurtle(turtle: TurtleView | null): void {
    this.turtle = turtle;
    this.invalidate();
  }

  setGhost(ghost: Segment[] | null): void {
    this.ghost = ghost;
    this.rebuildGhost();
    this.refit();
    this.invalidate();
  }

  private upload(b: Batch): void {
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, b.buffer);
    const total = b.count * FLOATS_PER_VERTEX;
    if (b.capacity < total) {
      const cap = Math.max(total, b.capacity * 2, FLOATS_PER_VERTEX * 6 * 256);
      gl.bufferData(gl.ARRAY_BUFFER, cap * 4, gl.DYNAMIC_DRAW);
      b.capacity = cap;
      b.uploaded = 0;
    }
    if (b.uploaded < total) {
      gl.bufferSubData(gl.ARRAY_BUFFER, b.uploaded * 4, b.data.subarray(b.uploaded, total));
      b.uploaded = total;
    }
  }

  // --- camera ------------------------------------------------------------------------------------------------

  private sceneBounds(): { center: V3; radius: number } {
    const min: V3 = [0, 0, 0], max: V3 = [0, 0, 0];
    const grow = (p: V3) => {
      for (let i = 0; i < 3; i++) {
        if (p[i] < min[i]) min[i] = p[i];
        if (p[i] > max[i]) max[i] = p[i];
      }
    };
    for (const s of this.segments) { grow(s.from); grow(s.to); }
    if (this.ghost) for (const s of this.ghost) { grow(s.from); grow(s.to); }
    if (this.turtle) grow(this.turtle.pos);
    const center: V3 = [(min[0] + max[0]) / 2, (min[1] + max[1]) / 2, (min[2] + max[2]) / 2];
    const radius = Math.max(Math.hypot(max[0] - min[0], max[1] - min[1], max[2] - min[2]) / 2, 20);
    return { center, radius };
  }

  private fitDistance(radius: number): number {
    const aspect = this.width / this.height;
    const half = Math.atan(Math.tan(FOV / 2) * Math.min(1, aspect));
    return (radius / Math.sin(half)) * 1.12;
  }

  private refit(snap = false): void {
    const { center, radius } = this.sceneBounds();
    this.radius = radius;
    if (!this.autoFit) return;
    const goal = { target: center, dist: this.fitDistance(radius) };
    if (snap) {
      this.target = goal.target;
      this.dist = goal.dist;
      this.goal = null;
    } else {
      this.goal = goal;
    }
  }

  fit(snap = false): void {
    this.autoFit = true;
    this.refit(snap);
    this.invalidate();
  }

  /** Default orientation and a view of the whole drawing. */
  resetView(snap = false): void {
    this.yaw = DEFAULT_YAW;
    this.pitch = DEFAULT_PITCH;
    this.fit(snap);
  }

  private eye(): V3 {
    const cp = Math.cos(this.pitch);
    return add(this.target, vscale([Math.sin(this.yaw) * cp, -Math.cos(this.yaw) * cp, Math.sin(this.pitch)], this.dist));
  }

  private basis(): { right: V3; up: V3; forward: V3 } {
    const forward = norm(sub(this.target, this.eye()));
    const right = norm(cross(forward, [0, 0, 1]));
    const up = cross(right, forward);
    return { right, up, forward };
  }

  // --- rendering ---------------------------------------------------------------------------------------------

  refresh(): void {
    this.resize();
  }

  private resize(): void {
    const rect = this.el.getBoundingClientRect();
    this.dpr = window.devicePixelRatio || 1;
    this.width = Math.max(1, Math.floor(rect.width));
    this.height = Math.max(1, Math.floor(rect.height));
    this.canvas.width = Math.floor(this.width * this.dpr);
    this.canvas.height = Math.floor(this.height * this.dpr);
    this.canvas.style.width = this.width + "px";
    this.canvas.style.height = this.height + "px";
    this.refit(!this.hasBeenSized);
    this.hasBeenSized = true;
    this.invalidate();
  }
  private hasBeenSized = false;

  private invalidate(): void {
    this.dirty = true;
    if (!this.raf) this.raf = requestAnimationFrame(() => this.frame());
  }

  private frame(): void {
    this.raf = 0;
    if (this.goal) {
      const g = this.goal;
      const k = 0.25;
      this.target = add(this.target, vscale(sub(g.target, this.target), k));
      this.dist *= Math.pow(g.dist / this.dist, k);
      const near = Math.hypot(...sub(g.target, this.target)) < this.radius * 0.002 && Math.abs(g.dist / this.dist - 1) < 0.002;
      if (near) {
        this.target = g.target;
        this.dist = g.dist;
        this.goal = null;
      }
      this.dirty = true;
    }
    if (this.dirty) {
      this.dirty = false;
      this.render();
    }
    if (this.goal) this.raf = requestAnimationFrame(() => this.frame());
  }

  private buildDeco(): void {
    const R = Math.max(this.radius, 40);
    const step = niceStep((R * 2.4) / 12);
    const extent = Math.ceil((R * 1.25) / step) * step;
    const pal = palette();
    const key = `${step}|${extent}|${pal.grid}|${pal.gridMajor}|${pal.axisX}|${pal.axisY}|${pal.axisZ}`;
    if (key === this.decoKey) return;
    this.decoKey = key;
    const b = this.deco;
    b.count = 0;
    b.uploaded = 0;
    const grid = parseCssColor(pal.grid), major = parseCssColor(pal.gridMajor);
    for (let v = -extent; v <= extent + 1e-9; v += step) {
      const isMajor = Math.abs(v / (step * 5) - Math.round(v / (step * 5))) < 1e-9;
      const c = isMajor ? major : grid;
      this.pushSegment(b, [v, -extent, 0], [v, extent, 0], c, 1);
      this.pushSegment(b, [-extent, v, 0], [extent, v, 0], c, 1);
    }
    this.pushSegment(b, [0, 0, 0], [extent, 0, 0], parseCssColor(pal.axisX), 2.5);
    this.pushSegment(b, [0, 0, 0], [0, extent, 0], parseCssColor(pal.axisY), 2.5);
    this.pushSegment(b, [0, 0, 0], [0, 0, extent], parseCssColor(pal.axisZ), 2.5);
    this.axisEnd = extent;
  }
  private axisEnd = 100;

  private buildMarker(): void {
    const b = this.marker;
    b.count = 0;
    b.uploaded = 0;
    const t = this.turtle;
    if (!t) return;
    const L = Math.max(this.dist * 0.06, 4);
    const p = t.pos as V3, hd = t.heading as V3, r = t.right as V3, u = t.up as V3;
    const tip = add(p, vscale(hd, L));
    const pal = palette();
    const head = parseCssColor(displayColor(t.penDown ? t.color : "#c1763d", effectiveTheme()));
    this.pushSegment(b, p, tip, head, 4);
    const back = sub(tip, vscale(hd, L * 0.3));
    for (const side of [vscale(r, L * 0.2), vscale(r, -L * 0.2), vscale(u, L * 0.2), vscale(u, -L * 0.2)]) {
      this.pushSegment(b, tip, add(back, side), head, 3);
    }
    this.pushSegment(b, p, add(p, vscale(u, L * 0.55)), parseCssColor(pal.axisZ), 3);
    this.pushSegment(b, p, add(p, vscale(r, L * 0.55)), parseCssColor(pal.axisX), 3);
  }

  private render(): void {
    const gl = this.gl;
    if (gl.isContextLost()) return;
    const pal = palette();
    const aspect = this.width / this.height;
    const view = lookAt(this.eye(), this.target, [0, 0, 1]);
    const far = this.dist + this.radius * 40 + 1000;
    this.vp = multiply(perspective(FOV, aspect, 0.05, far), view);

    this.buildDeco();
    this.buildMarker();

    const bg = parseCssColor(pal.paper);
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.clearColor(bg[0], bg[1], bg[2], 1);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.useProgram(this.program);
    gl.uniformMatrix4fv(this.uni.uVP, false, this.vp);
    gl.uniform2f(this.uni.uViewport, this.canvas.width, this.canvas.height);
    gl.uniform2f(this.uni.uDepth, this.dist, Math.max(this.radius, 10));
    gl.uniform3f(this.uni.uFog, bg[0], bg[1], bg[2]);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

    gl.disable(gl.DEPTH_TEST);
    gl.uniform1f(this.uni.uFogAmount, 0.0);
    this.drawBatch(this.deco);
    this.drawBatch(this.ghostBatch);
    gl.enable(gl.DEPTH_TEST);
    gl.uniform1f(this.uni.uFogAmount, 0.5);
    this.drawBatch(this.drawing);
    gl.disable(gl.DEPTH_TEST);
    gl.uniform1f(this.uni.uFogAmount, 0.0);
    this.drawBatch(this.marker);

    this.placeLabels();
  }

  private drawBatch(b: Batch): void {
    if (!b.count) return;
    const gl = this.gl;
    this.upload(b);
    const stride = FLOATS_PER_VERTEX * 4;
    const attr = (name: string, size: number, offset: number) => {
      const l = this.loc[name];
      gl.enableVertexAttribArray(l);
      gl.vertexAttribPointer(l, size, gl.FLOAT, false, stride, offset * 4);
    };
    attr("aA", 3, 0);
    attr("aB", 3, 3);
    attr("aCorner", 2, 6);
    attr("aColor", 4, 8);
    attr("aWidth", 1, 12);
    gl.drawArrays(gl.TRIANGLES, 0, b.count);
  }

  private screenOf(p: V3): [number, number] | null {
    const c = project(this.vp, p);
    if (c[3] <= 0.05) return null;
    return [(c[0] / c[3] * 0.5 + 0.5) * this.width, (1 - (c[1] / c[3] * 0.5 + 0.5)) * this.height];
  }

  private placeLabels(): void {
    const e = this.axisEnd;
    const put = (el: HTMLElement, p: V3) => {
      const s = this.screenOf(p);
      if (!s) { el.style.display = "none"; return; }
      el.style.display = "";
      el.style.transform = `translate(${Math.round(Math.min(Math.max(s[0], 8), this.width - 18))}px, ${Math.round(Math.min(Math.max(s[1], 8), this.height - 22))}px)`;
    };
    put(this.labels.x, [e * 1.04, 0, 0]);
    put(this.labels.y, [0, e * 1.04, 0]);
    put(this.labels.z, [0, 0, e * 1.04]);
  }

  /** PNG of the current 3D view. */
  exportPNG(): Promise<Blob> {
    this.render();
    return new Promise((resolve, reject) => this.canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("PNG"))), "image/png"));
  }

  // --- interaction -------------------------------------------------------------------------------------------

  private userMoved(): void {
    this.autoFit = false;
    this.goal = null;
    this.invalidate();
  }

  private pointerDown(e: PointerEvent): void {
    this.canvas.setPointerCapture(e.pointerId);
    this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY, button: e.button });
    this.lastPinch = null;
    this.canvas.classList.add("grabbing");
  }

  private pointerMove(e: PointerEvent): void {
    const p = this.pointers.get(e.pointerId);
    if (!p) return;
    const dx = e.clientX - p.x, dy = e.clientY - p.y;
    p.x = e.clientX;
    p.y = e.clientY;
    if (this.pointers.size === 1) {
      const pan = p.button === 2 || p.button === 1 || e.shiftKey || e.ctrlKey || e.metaKey;
      if (pan) this.pan(dx, dy);
      else this.orbit(dx, dy);
    } else if (this.pointers.size === 2) {
      const [a, b] = [...this.pointers.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
      if (this.lastPinch) {
        this.dist = clamp(this.dist * (this.lastPinch.dist / Math.max(dist, 1)), this.radius * 0.02 + 0.5, this.radius * 30 + 500);
        this.pan(mx - this.lastPinch.x, my - this.lastPinch.y);
      }
      this.lastPinch = { dist, x: mx, y: my };
    }
    this.userMoved();
  }

  private pointerUp(e: PointerEvent): void {
    this.pointers.delete(e.pointerId);
    this.lastPinch = null;
    if (!this.pointers.size) this.canvas.classList.remove("grabbing");
  }

  private orbit(dx: number, dy: number): void {
    this.yaw -= dx * 0.008;
    this.pitch = clamp(this.pitch + dy * 0.008, (-89 * Math.PI) / 180, (89 * Math.PI) / 180);
  }

  private pan(dx: number, dy: number): void {
    const { right, up } = this.basis();
    const k = (2 * this.dist * Math.tan(FOV / 2)) / this.height;
    this.target = add(this.target, add(vscale(right, -dx * k), vscale(up, dy * k)));
  }

  private wheel(e: WheelEvent): void {
    e.preventDefault();
    this.zoomBy(Math.exp(e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0015)));
  }

  /** factor > 1 moves the camera away. */
  zoomBy(factor: number): void {
    this.dist = clamp(this.dist * factor, this.radius * 0.02 + 0.5, this.radius * 30 + 500);
    this.userMoved();
  }

  private key(e: KeyboardEvent): void {
    const pan = e.shiftKey;
    switch (e.key) {
      case "ArrowLeft": pan ? this.pan(30, 0) : this.orbit(-30, 0); break;
      case "ArrowRight": pan ? this.pan(-30, 0) : this.orbit(30, 0); break;
      case "ArrowUp": pan ? this.pan(0, 30) : this.orbit(0, 30); break;
      case "ArrowDown": pan ? this.pan(0, -30) : this.orbit(0, -30); break;
      case "+": case "=": this.zoomBy(0.8); return;
      case "-": case "_": this.zoomBy(1.25); return;
      case "0": this.resetView(); return;
      default: return;
    }
    e.preventDefault();
    this.userMoved();
  }
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
EOF
