import { describe, expect, test } from "bun:test";
import { REFERENCE, referenceCommands, referenceExamples } from "../src/data/reference";
import { run } from "../src/lang";

// Aliasy z tabeli poleceń w opisie produktu – niezależna lista, nie wyprowadzona z kodu.
const BRIEF_ALIASES = [
  "np", "naprzod", "naprzód", "fd", "forward", "ws", "wstecz", "bk", "back", "pw", "prawo", "rt", "right",
  "lw", "lewo", "lt", "left", "pod", "podnies", "podnieś", "pu", "penup", "opu", "opusc", "opuść", "pd", "pendown",
  "kolor", "color", "grubosc", "grubość", "width", "powtorz", "powtórz", "repeat", "niech", "let",
  "jeśli", "jesli", "if", "jeżeli", "jezeli", "ifelse", "stop", "dom", "home", "czyść", "czysc", "cs", "clearscreen",
  "gora", "góra", "pitchup", "dol", "dół", "pitchdown", "pp", "przechylprawo", "rr", "rollright",
  "pl", "przechyllewo", "rl", "rollleft", "nrpowt", "repcount", "oto", "to", "już", "juz", "end",
];

describe("opis poleceń", () => {
  test("dokumentuje każdy alias z tabeli poleceń (po polsku i angielsku)", () => {
    const documented = new Set(referenceCommands().flatMap((c) => c.names.map((n) => n.toLowerCase())));
    for (const alias of BRIEF_ALIASES) expect(documented.has(alias)).toBe(true);
  });
  test("ma sekcje o wyrażeniach, zmiennych, warunkach, procedurach i limitach", () => {
    const titles = REFERENCE.map((s) => s.title.toLowerCase()).join("|");
    for (const word of ["wyraż", "zmienn", "warunk", "procedur", "limit", "błęd", "3d"]) expect(titles).toContain(word);
  });
  test("każde polecenie ma opis i co najmniej jeden przykład", () => {
    for (const c of referenceCommands()) {
      expect(c.summary.length).toBeGreaterThan(10);
      expect(c.examples.length).toBeGreaterThan(0);
    }
  });
  test("wszystkie przykłady działają tak, jak opisano (bez błędu albo z opisanym błędem)", () => {
    const examples = referenceExamples();
    expect(examples.length).toBeGreaterThan(30);
    for (const ex of examples) {
      const r = run(ex.code, ex.mode);
      if (ex.expectError) {
        expect(r.error, ex.code).toMatchObject(ex.expectError);
      } else {
        expect(r.error, ex.code).toBeNull();
        expect(r.segments.length, ex.code).toBeGreaterThan(0);
      }
    }
  });
});
