import type { Mode } from "../lang";

export interface RefExample {
  code: string;
  mode: Mode;
  /** Set when the example demonstrates an error; the position is checked by the tests. */
  expectError?: { line: number; column: number };
  caption?: string;
}

export interface RefCommand {
  type: "command";
  names: string[];
  usage: string;
  summary: string;
  details?: string[];
  examples: RefExample[];
}

export type Block =
  | { type: "p"; text: string }
  | { type: "list"; items: string[] }
  | { type: "code"; example: RefExample }
  | { type: "table"; head: string[]; rows: string[][] }
  | RefCommand;

export interface Section {
  id: string;
  title: string;
  blocks: Block[];
}

const ex = (code: string, mode: Mode = "2d", extra: Partial<RefExample> = {}): RefExample => ({ code, mode, ...extra });
const code = (c: string, mode: Mode = "2d", extra: Partial<RefExample> = {}): Block => ({ type: "code", example: ex(c, mode, extra) });
const p = (text: string): Block => ({ type: "p", text });

