export function referenceCommands(): RefCommand[] {
  return REFERENCE.flatMap((s) => s.blocks.filter((b): b is RefCommand => b.type === "command"));
}

export function referenceExamples(): RefExample[] {
  return REFERENCE.flatMap((s) =>
    s.blocks.flatMap((b) => (b.type === "command" ? b.examples : b.type === "code" ? [b.example] : [])),
  );
}
