    const gutter = h("div", { class: "editor-gutter", "aria-hidden": "true" }, this.gutterInner, this.gutterMark, this.gutterArrow);
    this.el = h("div", { class: "editor" }, gutter, h("div", { class: "editor-code" }, this.layer, this.textarea, this.measure));

