      this.render();
      opts.onInput(this.textarea.value);
    });
    this.textarea.addEventListener("scroll", () => this.syncScroll());
    this.textarea.addEventListener("keydown", (e) => this.keydown(e));
    new ResizeObserver(() => this.positionMarks()).observe(this.el);
  }

