  setValue(value: string): void {
    if (this.textarea.value === value) return;
    this.textarea.value = value;
    this.render();
  }

  focus(): void {
    this.textarea.focus();
  }

  setError(error: LogoError | null): void {
    this.error = error;
    this.positionMarks();
  }

  setCurrentLine(line: number | null): void {
    this.currentLine = line;
    this.positionMarks();
    if (line !== null) this.scrollToLine(line);
  }

