    const src = this.textarea.value;
    let html = "";
    let pos = 0;
    for (const s of highlight(src)) {
      html += esc(src.slice(pos, s.start)) + `<span class="t-${s.kind}">${esc(src.slice(s.start, s.end))}</span>`;
      pos = s.end;
    }
    this.hl.innerHTML = html + esc(src.slice(pos)) + "\n";
    const lines = src.split("\n").length;
    if (lines !== this.lines) {
      this.lines = lines;
      let n = "";
      for (let i = 1; i <= lines; i++) n += i + "\n";
      this.gutterInner.textContent = n;
