    return { lh, cw, padTop: parseFloat(cs.paddingTop) || 0, padLeft: parseFloat(cs.paddingLeft) || 0 };
  }

  private syncScroll(): void {
    const { scrollLeft: sl, scrollTop: st } = this.textarea;
    this.layer.style.transform = `translate(${-sl}px, ${-st}px)`;
    this.gutterInner.style.transform = `translateY(${-st}px)`;
    this.positionMarks();
