    const { lh, cw, padTop, padLeft } = this.metrics();
    const st = this.textarea.scrollTop;
    const band = (el: HTMLElement, line: number | null) => {
      el.hidden = line === null;
      if (line !== null) {
        el.style.top = padTop + (line - 1) * lh + "px";
        el.style.height = lh + "px";
      }
    };
