    this.gutterMark.hidden = !this.error;
    this.squiggle.hidden = !this.error;
    if (this.error) {
      const { line, column } = this.error;
      this.gutterMark.style.top = padTop + (line - 1) * lh - st + "px";
      const text = this.textarea.value.split("\n")[line - 1] ?? "";
      const rest = text.slice(column - 1);
      const len = Math.max(1, /^[^\s[\]()]+/.exec(rest)?.[0].length ?? 1);
      this.squiggle.style.top = padTop + line * lh - 5 + "px";
      this.squiggle.style.left = padLeft + (column - 1) * cw + "px";
      this.squiggle.style.width = len * cw + "px";
      this.squiggle.title = this.error.message;
    }
  }

  private scrollToLine(line: number): void {
    const { lh, padTop } = this.metrics();
    const top = padTop + (line - 1) * lh;
    const ta = this.textarea;
    if (top < ta.scrollTop + lh || top > ta.scrollTop + ta.clientHeight - 2 * lh) ta.scrollTop = Math.max(0, top - ta.clientHeight / 3);
  }

  private keydown(e: KeyboardEvent): void {
    const ta = this.textarea;
    if (e.key === "Escape") {
      // Leave the editor so that Tab continues through the page instead of being swallowed.
      ta.blur();
      return;
    }
    if (e.key === "Enter" && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && ta.selectionStart === ta.selectionEnd) {
      const before = ta.value.slice(0, ta.selectionStart);
      const lineStart = before.lastIndexOf("\n") + 1;
      const line = before.slice(lineStart);
      let indent = /^[ \t]*/.exec(line)![0];
      if (/\[\s*(;.*)?$/.test(line) || /^\s*(oto|to)\b/i.test(line)) indent += "  ";
      e.preventDefault();
      this.insert("\n" + indent);
    }
  }

  private insert(text: string): void {
    const ta = this.textarea;
    // execCommand keeps the browser's undo stack intact; setRangeText is the fallback.
    if (!document.execCommand?.("insertText", false, text)) {
      ta.setRangeText(text, ta.selectionStart, ta.selectionEnd, "end");
      ta.dispatchEvent(new Event("input", { bubbles: true }));
    }
  }
}
