    const cancel = h("button", { class: "btn", type: "button", "on:click": () => dialog.close() }, opts.cancelLabel ?? "Anuluj");
    const dialog = openDialog(opts.title, [h("p", null, opts.message)], [cancel, ok]);
    dialog.addEventListener("close", () => resolve(result));
    cancel.focus();
  });
}

export function shortcutsDialog(): void {
  const rows = SHORTCUTS.map((s) =>
    h("tr", null,
      h("th", { scope: "row" }, ...s.keys.flatMap((k, i) => [i ? " + " : "", h("kbd", null, keyLabel(k))])),
      h("td", null, s.action)),
  );
  const close = h("button", { class: "btn primary", type: "button", "on:click": () => dialog.close() }, "Zamknij");
  const dialog = openDialog("Skróty klawiszowe", [h("table", { class: "shortcuts" }, h("tbody", null, ...rows))], [close]);
  close.focus();
}

export function shareDialog(link: string, copied: boolean): void {
  const input = h("input", { class: "share-input", type: "text", readonly: true, value: link, "aria-label": "Stały odnośnik do programu" });
  const status = h("p", { class: "muted", role: "status" }, copied ? "Odnośnik skopiowano do schowka." : "Zaznacz odnośnik i skopiuj go (Ctrl+C).");
  const copy = h("button", { class: "btn", type: "button", "on:click": async () => {
    try {
      await navigator.clipboard.writeText(link);
      status.textContent = "Odnośnik skopiowano do schowka.";
    } catch {
      input.select();
      status.textContent = "Nie udało się skopiować automatycznie – odnośnik jest zaznaczony, naciśnij Ctrl+C.";
    }
  } }, icon("link"), "Kopiuj");
  const close = h("button", { class: "btn primary", type: "button", "on:click": () => dialog.close() }, "Zamknij");
  const dialog = openDialog("Odnośnik do programu", [
    h("p", null, "Każdy, kto otworzy ten odnośnik, zobaczy ten program i od razu go uruchomi. Program jest zapisany w samym adresie – nic nie jest wysyłane na serwer."),
    h("div", { class: "share-row" }, input, copy),
    status,
  ], [close]);
  input.select();
}

let toastRegion: HTMLElement | null = null;

export function toast(message: string, kind: "info" | "error" = "info"): void {
  if (!toastRegion) {
    toastRegion = h("div", { class: "toasts", role: "status", "aria-live": "polite" });
    document.body.append(toastRegion);
  }
  const el = h("div", { class: `toast ${kind}` }, message);
  toastRegion.append(el);
  setTimeout(() => el.remove(), 4500);
}

export function download(filename: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const a = h("a", { href: url, download: filename, hidden: true });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
