import { ChallengeBook, type Challenge, type Verdict } from "../core/challenges";
import { Workspace, type Status } from "../core/workspace";
import { EXAMPLES } from "../data/examples";
import type { Mode } from "../lang";
import { confirmDialog, download, shareDialog, shortcutsDialog, toast, keyLabel } from "./dialogs";
import { clear, h, icon } from "./dom";
import { Editor } from "./editor";
import { View2D } from "./view2d";
import { View3D, webglSupport } from "./view3d";

/** Animation speeds (statements per second) on the slider. */
const SPEEDS = [1, 3, 10, 30, 100, 400, Infinity];
const speedIndex = (v: number) => {
  let best = 0;
  SPEEDS.forEach((s, i) => { if (Math.abs(Math.log((s === Infinity ? 1e6 : s) / (v === Infinity ? 1e6 : v))) < Math.abs(Math.log((SPEEDS[best] === Infinity ? 1e6 : SPEEDS[best]) / (v === Infinity ? 1e6 : v)))) best = i; });
  return best;
};
const speedLabel = (v: number) => (v === Infinity ? "maksymalna" : v === 1 ? "1 polecenie/s" : `${v} poleceń/s`);

export interface ChallengeContext {
  challenge: Challenge;
  book: ChallengeBook;
  nextHref: string | null;
}

export interface WorkspacePageOptions {
  ws: Workspace;
  navigate(hash: string): void;
  challenge?: ChallengeContext;
}

export class WorkspacePage {
  readonly el: HTMLElement;
  private ws: Workspace;
  private editor: Editor;
  private view2d = new View2D();
  private view3d: View3D | null = null;
  private viewHost: HTMLElement;
  private panes: HTMLElement;
  private webgl = webglSupport();
  private statusEl: HTMLElement;
  private bannerEl: HTMLElement;
  private btnRun!: HTMLButtonElement;
  private btnStep!: HTMLButtonElement;
  private btnPause!: HTMLButtonElement;
  private btnReset!: HTMLButtonElement;
  private speed!: HTMLInputElement;
  private speedOut!: HTMLElement;
  private modeButtons: Record<Mode, HTMLButtonElement> = {} as never;
  private exampleSelect: HTMLSelectElement | null = null;
  private menuPanel!: HTMLElement;
  private menuButton!: HTMLButtonElement;
  private fileInput!: HTMLInputElement;
  private disabled3d!: HTMLElement;
  private tabCode!: HTMLButtonElement;
  private tabView!: HTMLButtonElement;
  private toolsEl!: HTMLElement;
  private verdictEl: HTMLElement | null = null;
  private ghostOn = true;
  private lastFrame = 0;
  private animating = false;
  private unsubscribe: () => void;
  private active = false;
  private shown2d = true;

  constructor(private opts: WorkspacePageOptions) {
    this.ws = opts.ws;
    const c = opts.challenge;

    this.statusEl = h("p", { class: "status", id: `status-${uid()}`, role: "status", "aria-live": "polite" });
    this.editor = new Editor({ label: "Edytor programu Logo", describedBy: this.statusEl.id, onInput: (v) => this.ws.setSource(v) });
    this.bannerEl = h("div", { class: "banner-stack" });
    this.disabled3d = h("div", { class: "view-off", hidden: true, role: "note" }, h("h3", null, "Widok 3D jest wyłączony"), h("p", null, this.webgl.reason));
    this.viewHost = h("div", { class: "view-host" }, this.view2d.el, this.disabled3d);
    this.toolsEl = this.buildViewTools();

    const diag = h("div", { class: "diag" }, this.statusEl);
    const codePane = h("section", { class: "pane pane-code", "aria-label": "Program" }, this.editor.el, diag);
    const viewPane = h("section", { class: "pane pane-view", "aria-label": "Rysunek" }, this.viewHost, this.toolsEl, h("p", { class: "view-hint" }, ""));
    this.panes = h("div", { class: "panes show-code" }, codePane, viewPane);

    this.tabCode = h("button", { class: "tab", type: "button", role: "tab", "aria-selected": "true", "on:click": () => this.showTab("code") }, "Kod");
    this.tabView = h("button", { class: "tab", type: "button", role: "tab", "aria-selected": "false", "on:click": () => this.showTab("view") }, "Rysunek");
    const tabs = h("div", { class: "pane-tabs", role: "tablist", "aria-label": "Panel" }, this.tabCode, this.tabView);

    this.el = h("div", { class: "workspace" },
      c ? this.buildChallengePanel(c) : null,
      this.buildToolbar(),
      this.bannerEl,
      tabs,
      this.panes,
    );

    if (this.webgl.ok === false) this.bannerEl.append(h("div", { class: "banner warn", role: "note" }, h("strong", null, "Widok 3D jest wyłączony. "), this.webgl.reason));

    this.unsubscribe = this.ws.subscribe(() => this.render());
    this.render();
    this.view2d.fit(true);
  }

  // --- construction ------------------------------------------------------------------------------------------

  private button(label: string, iconName: string, onClick: () => void, extra: Record<string, unknown> = {}): HTMLButtonElement {
    return h("button", { class: "btn", type: "button", "on:click": onClick, ...extra }, icon(iconName), h("span", { class: "btn-label" }, label));
  }

  private buildToolbar(): HTMLElement {
    this.btnRun = this.button("Uruchom", "play", () => this.run(), { class: "btn primary", "aria-keyshortcuts": "Control+Enter", title: "Uruchom program (Ctrl+Enter)" });
    this.btnStep = this.button("Krok", "step", () => this.step(), { "aria-keyshortcuts": "Control+Shift+Enter", title: "Wykonaj jeden krok (Ctrl+Shift+Enter)" });
    this.btnPause = this.button("Pauza", "pause", () => this.togglePause(), { "aria-keyshortcuts": "Alt+P", title: "Pauza / wznów (Alt+P)" });
    this.btnReset = this.button("Reset", "reset", () => this.ws.reset(), { "aria-keyshortcuts": "Alt+R", title: "Wyczyść rysunek i zatrzymaj program (Alt+R)" });

    const speedId = `speed-${uid()}`;
    this.speed = h("input", { id: speedId, class: "speed", type: "range", min: 0, max: SPEEDS.length - 1, step: 1, value: speedIndex(this.ws.state.speed), "aria-describedby": `${speedId}-out`, "on:input": () => this.ws.setSpeed(SPEEDS[Number(this.speed.value)]) });
    this.speedOut = h("output", { id: `${speedId}-out`, for: speedId, class: "speed-out" });
    const speedBox = h("div", { class: "speed-box" }, h("label", { for: speedId }, "Szybkość"), this.speed, this.speedOut);

    const modeGroup = h("div", { class: "segmented", role: "radiogroup", "aria-label": "Tryb rysowania" });
    for (const mode of ["2d", "3d"] as Mode[]) {
      const b = h("button", { class: "seg", type: "button", role: "radio", "aria-checked": "false", "data-mode": mode, "on:click": () => this.chooseMode(mode) }, mode.toUpperCase());
      this.modeButtons[mode] = b;
      modeGroup.append(b);
    }
    if (!this.webgl.ok) {
      this.modeButtons["3d"].disabled = true;
      this.modeButtons["3d"].title = this.webgl.reason;
    }

    const run = h("div", { class: "group", role: "group", "aria-label": "Wykonanie" }, this.btnRun, this.btnStep, this.btnPause, this.btnReset);
    const left = [run, speedBox];
    const right: (HTMLElement | null)[] = [];

    if (!this.opts.challenge) {
      right.push(modeGroup);
      const id = `ex-${uid()}`;
      this.exampleSelect = h("select", { id, class: "select", "aria-label": "Wczytaj przykład", "on:change": () => this.loadExample() },
        h("option", { value: "" }, "Przykłady…"),
        h("optgroup", { label: "Rysunki płaskie (2D)" }, ...EXAMPLES.filter((e) => e.mode === "2d").map((e) => h("option", { value: e.id }, e.name))),
        h("optgroup", { label: "Przestrzeń (3D)" }, ...EXAMPLES.filter((e) => e.mode === "3d").map((e) => h("option", { value: e.id }, e.name))),
      );
      right.push(this.exampleSelect);
    }
    right.push(this.buildMenu());
    return h("div", { class: "toolbar", role: "toolbar", "aria-label": "Sterowanie programem" }, h("div", { class: "toolbar-left" }, ...left), h("div", { class: "toolbar-right" }, ...right));
  }

  private buildMenu(): HTMLElement {
    const items: [string, string, () => void][] = [
      ["link", "Kopiuj odnośnik do programu", () => this.share()],
      ["image", "Pobierz rysunek (PNG)", () => this.exportPNG()],
      ["download", "Pobierz program (.logo)", () => this.downloadProgram()],
      ["upload", "Otwórz plik .logo…", () => this.fileInput.click()],
      ["keyboard", "Skróty klawiszowe", () => shortcutsDialog()],
    ];
    const id = `menu-${uid()}`;
    this.menuPanel = h("div", { class: "menu-panel", id, hidden: true },
      ...items.map(([ic, label, fn]) => h("button", { class: "menu-item", type: "button", "on:click": () => { this.closeMenu(); fn(); } }, icon(ic), label)));
    this.menuButton = h("button", { class: "btn", type: "button", "aria-expanded": "false", "aria-controls": id, "on:click": () => this.toggleMenu() }, icon("download"), h("span", { class: "btn-label" }, "Plik i udostępnianie"));
    this.fileInput = h("input", { type: "file", accept: ".logo,.txt,text/plain", hidden: true, "aria-label": "Wybierz plik programu .logo", "on:change": () => this.openFile() });
    const wrap = h("div", { class: "menu" }, this.menuButton, this.menuPanel, this.fileInput);
    document.addEventListener("click", (e) => { if (!wrap.contains(e.target as Node)) this.closeMenu(); });
    wrap.addEventListener("keydown", (e) => { if (e.key === "Escape" && !this.menuPanel.hidden) { this.closeMenu(); this.menuButton.focus(); } });
    return wrap;
  }

  private toggleMenu(): void {
    const open = this.menuPanel.hidden;
    this.menuPanel.hidden = !open;
    this.menuButton.setAttribute("aria-expanded", String(open));
    if (open) (this.menuPanel.firstElementChild as HTMLElement | null)?.focus();
  }

  private closeMenu(): void {
    this.menuPanel.hidden = true;
    this.menuButton.setAttribute("aria-expanded", "false");
  }

  private buildViewTools(): HTMLElement {
    const tool = (label: string, content: Node, fn: () => void) => h("button", { class: "tool", type: "button", "aria-label": label, title: label, "on:click": fn }, content);
    return h("div", { class: "view-tools", role: "group", "aria-label": "Widok" },
      tool("Przybliż", h("span", { "aria-hidden": "true" }, "+"), () => this.activeView().zoomBy(this.shown2d ? 1.3 : 0.77)),
      tool("Oddal", h("span", { "aria-hidden": "true" }, "−"), () => this.activeView().zoomBy(this.shown2d ? 0.77 : 1.3)),
      tool("Dopasuj widok do rysunku", icon("fit"), () => this.activeView().fit()),
      tool("Zresetuj kamerę 3D", icon("home"), () => this.view3d?.resetView()),
    );
  }

  private buildChallengePanel(c: ChallengeContext): HTMLElement {
    const ghostId = `ghost-${uid()}`;
    const ghostBox = h("input", { type: "checkbox", id: ghostId, checked: true, "on:change": () => { this.ghostOn = ghostBox.checked; this.applyGhost(); } });
    const check = h("button", { class: "btn primary", type: "button", "on:click": () => this.submit() }, icon("check"), "Sprawdź rozwiązanie");
    this.verdictEl = h("div", { class: "verdict", role: "status", "aria-live": "polite" });
    return h("section", { class: "challenge-panel", "aria-label": "Zadanie" },
      h("div", { class: "challenge-head" },
        h("a", { class: "back", href: "#/zadania" }, "← Wszystkie zadania"),
        h("h1", null, c.challenge.title),
        h("span", { class: `badge badge-${c.challenge.mode}` }, c.challenge.mode.toUpperCase())),
      h("p", { class: "brief" }, c.challenge.brief),
      h("details", { class: "hint" }, h("summary", null, "Podpowiedź"), h("p", null, c.challenge.hint)),
      h("div", { class: "challenge-actions" }, check, h("label", { class: "check", for: ghostId }, ghostBox, " Pokaż wzór pod rysunkiem")),
      this.verdictEl,
    );
  }

  // --- behaviour ---------------------------------------------------------------------------------------------

  private activeView(): View2D | View3D {
    return this.ws.state.mode === "3d" && this.view3d ? this.view3d : this.view2d;
  }

  private ensure3d(): View3D | null {
    if (this.view3d) return this.view3d;
    if (!this.webgl.ok) return null;
    try {
      this.view3d = new View3D();
      this.view3d.el.hidden = true;
      this.viewHost.append(this.view3d.el);
      this.applyGhost();
    } catch {
      this.webgl = { ok: false, reason: "Nie udało się uruchomić WebGL, więc widok 3D jest wyłączony. Tryb 2D działa normalnie." };
      this.disabled3d.querySelector("p")!.textContent = this.webgl.reason;
      this.modeButtons["3d"].disabled = true;
      this.bannerEl.append(h("div", { class: "banner warn", role: "note" }, h("strong", null, "Widok 3D jest wyłączony. "), this.webgl.reason));
      return null;
    }
    return this.view3d;
  }

  private applyGhost(): void {
    const c = this.opts.challenge;
    const ghost = c && this.ghostOn ? c.challenge.target() : null;
    this.view2d.setGhost(c && c.challenge.mode === "2d" ? ghost : null);
    this.view3d?.setGhost(c && c.challenge.mode === "3d" ? ghost : null);
  }

  private chooseMode(mode: Mode): void {
    if (mode === "3d" && !this.webgl.ok) {
      toast(this.webgl.reason, "error");
      return;
    }
    this.ws.setMode(mode);
  }

  private run(): void {
    if (this.needs3dButOff()) return;
    this.showTab("view");
    this.ws.run();
  }

  private step(): void {
    if (this.needs3dButOff()) return;
    this.showTab("view");
    this.ws.step();
  }

  private needs3dButOff(): boolean {
    if (this.ws.state.mode === "3d" && !this.webgl.ok) {
      toast("Tryb 3D jest wyłączony – " + this.webgl.reason, "error");
      return true;
    }
    return false;
  }

  private togglePause(): void {
    if (this.ws.state.status === "running") this.ws.pause();
    else this.ws.resume();
  }

  private showTab(tab: "code" | "view"): void {
    this.panes.classList.toggle("show-code", tab === "code");
    this.panes.classList.toggle("show-view", tab === "view");
    this.tabCode.setAttribute("aria-selected", String(tab === "code"));
    this.tabView.setAttribute("aria-selected", String(tab === "view"));
  }

  private async loadExample(): Promise<void> {
    const id = this.exampleSelect!.value;
    this.exampleSelect!.value = "";
    if (!id) return;
    const example = EXAMPLES.find((e) => e.id === id)!;
    if (example.mode === "3d" && !this.webgl.ok) {
      toast(`Przykład „${example.name}” wymaga trybu 3D. ${this.webgl.reason}`, "error");
      return;
    }
    let result = this.ws.loadExample(id);
    if (result === "confirm") {
      const ok = await confirmDialog({
        title: `Wczytać przykład „${example.name}”?`,
        message: `Zastąpi on Twój bieżący program w trybie ${example.mode.toUpperCase()}. Poprzedni program zostanie zachowany i będzie można go przywrócić.`,
        okLabel: "Wczytaj przykład",
      });
      if (!ok) return;
      result = this.ws.loadExample(id, { replace: true });
    }
    if (result === "loaded") {
      this.showTab("view");
      this.ws.run();
    }
  }

  private share(): void {
    const link = this.ws.permalink(location.href);
    navigator.clipboard?.writeText(link).then(
      () => shareDialog(link, true),
      () => shareDialog(link, false),
    ) ?? shareDialog(link, false);
  }

  private async exportPNG(): Promise<void> {
    try {
      const blob = await this.activeView().exportPNG();
      download(`rysunek-${this.ws.state.mode}.png`, blob);
    } catch {
      toast("Nie udało się wyeksportować obrazu.", "error");
    }
  }

  private downloadProgram(): void {
    const f = this.ws.exportFile();
    download(f.filename, new Blob([f.text], { type: "text/plain;charset=utf-8" }));
  }

  private async openFile(): Promise<void> {
    const file = this.fileInput.files?.[0];
    this.fileInput.value = "";
    if (!file) return;
    try {
      const text = await file.text();
      this.ws.importFile(file.name, text);
      toast(`Wczytano plik ${file.name}.`);
    } catch {
      toast("Nie udało się odczytać pliku.", "error");
    }
  }

  private submit(): void {
    const c = this.opts.challenge!;
    this.ws.runToEnd();
    const v: Verdict = c.book.submit(c.challenge.id, this.ws.state.source);
    this.showVerdict(v);
  }

  private showVerdict(v: Verdict): void {
    const c = this.opts.challenge!;
    const el = this.verdictEl!;
    clear(el);
    el.className = `verdict ${v.passed ? "pass" : "fail"}`;
    el.append(h("strong", null, v.passed ? "Zadanie zaliczone! " : "Jeszcze nie. "), v.reason);
    if (v.passed && c.nextHref) el.append(" ", h("a", { href: c.nextHref }, "Następne zadanie →"));
  }

  /** Shows the verdict stored from an earlier session, so progress is visible when the page opens. */
  private showSavedProgress(): void {
    const c = this.opts.challenge;
    if (!c || !this.verdictEl || this.verdictEl.childNodes.length) return;
    const r = c.book.results()[c.challenge.id];
    if (r?.passed) {
      this.verdictEl.className = "verdict pass";
      this.verdictEl.append(h("strong", null, "Zadanie zaliczone. "), "Możesz je rozwiązać inaczej albo wrócić do listy zadań.");
    }
  }

  // --- rendering ---------------------------------------------------------------------------------------------

  private render(): void {
    const s = this.ws.state;
    this.editor.setValue(s.source);
    this.editor.setError(s.status === "error" ? s.error : null);
    this.editor.setCurrentLine(s.status === "running" || s.status === "paused" ? s.currentLine : null);

    // views
    const want3d = s.mode === "3d";
    const v3 = want3d ? this.ensure3d() : this.view3d;
    this.shown2d = !want3d;
    this.view2d.el.hidden = want3d;
    if (this.view3d) this.view3d.el.hidden = !want3d || !v3;
    this.disabled3d.hidden = !(want3d && !v3);
    this.view2d.setSegments(want3d ? [] : s.segments);
    this.view2d.setTurtle(want3d ? null : s.turtle);
    if (this.view3d) {
      this.view3d.setSegments(want3d ? s.segments : []);
      this.view3d.setTurtle(want3d ? s.turtle : null);
    }
    this.toolsEl.classList.toggle("is-3d", want3d);
    for (const m of ["2d", "3d"] as Mode[]) {
      this.modeButtons[m].setAttribute("aria-checked", String(s.mode === m));
      this.modeButtons[m].classList.toggle("active", s.mode === m);
    }
    this.panes.parentElement?.setAttribute("data-mode", s.mode);
    const hint = this.el.querySelector(".view-hint");
    if (hint) hint.textContent = want3d
      ? "Przeciągnij: obrót · Shift lub prawy przycisk: przesuwanie · kółko lub szczypanie: zoom · dwuklik: reset"
      : "Przeciągnij: przesuwanie · kółko lub szczypanie: zoom · dwuklik: dopasuj";

    // controls
    const running = s.status === "running", paused = s.status === "paused";
    this.btnPause.disabled = !(running || paused);
    const pauseLabel = this.btnPause.querySelector(".btn-label")!;
    pauseLabel.textContent = paused ? "Wznów" : "Pauza";
    this.btnPause.replaceChild(icon(paused ? "play" : "pause"), this.btnPause.querySelector("svg")!);
    this.btnRun.querySelector(".btn-label")!.textContent = paused ? "Wznów" : "Uruchom";
    this.btnReset.disabled = s.status === "idle" && s.segments.length === 0;
    this.speed.value = String(speedIndex(s.speed));
    this.speedOut.textContent = speedLabel(s.speed);
    this.renderBanner();
    this.renderStatus(s.status);
    this.showSavedProgress();

    if (running && !this.animating) this.startLoop();
  }

  private renderBanner(): void {
    const s = this.ws.state;
    this.bannerEl.querySelectorAll(".banner.backup").forEach((n) => n.remove());
    if (s.backup) {
      this.bannerEl.append(
        h("div", { class: "banner backup", role: "note" },
          h("span", null, `Poprzedni szkic (${s.backup.mode.toUpperCase()}) został zachowany.`),
          h("button", { class: "btn small", type: "button", "on:click": () => this.ws.restoreBackup() }, icon("undo", 16), "Przywróć"),
          h("button", { class: "btn small", type: "button", "aria-label": "Odrzuć kopię poprzedniego szkicu", "on:click": () => this.ws.discardBackup() }, icon("close", 16), "Odrzuć")),
      );
    }
  }

  private renderStatus(status: Status): void {
    const s = this.ws.state;
    let text: string;
    this.statusEl.classList.toggle("is-error", status === "error");
    this.statusEl.setAttribute("role", status === "error" ? "alert" : "status");
    switch (status) {
      case "idle": text = s.notice ?? "Gotowy. Naciśnij „Uruchom” lub „Krok”."; break;
      case "running": text = `Działa… ${s.currentLine ? `następny wiersz: ${s.currentLine}` : ""}`; break;
      case "paused": text = s.currentLine ? `Wstrzymano przed wierszem ${s.currentLine}.` : "Wstrzymano."; break;
      case "finished": text = `Zakończono: ${s.segments.length} ${plural(s.segments.length, "odcinek", "odcinki", "odcinków")}.`; break;
      case "error": text = `Błąd (wiersz ${s.error!.line}, kolumna ${s.error!.column}): ${s.error!.message}${s.segments.length ? ` Narysowano ${s.segments.length} ${plural(s.segments.length, "odcinek", "odcinki", "odcinków")}.` : " Nic nie narysowano."}`; break;
    }
    this.statusEl.textContent = text;
  }

  private startLoop(): void {
    this.animating = true;
    this.lastFrame = performance.now();
    const loop = (now: number) => {
      if (this.ws.state.status !== "running") {
        this.animating = false;
        return;
      }
      this.ws.tick(Math.min(now - this.lastFrame, 100));
      this.lastFrame = now;
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  }

  // --- lifecycle and hooks -----------------------------------------------------------------------------------

  private onKey = (e: KeyboardEvent) => {
    if (!this.active || e.defaultPrevented) return;
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key === "Enter") {
      e.preventDefault();
      if (e.shiftKey) this.step();
      else this.run();
    } else if (e.altKey && !mod && e.code === "KeyP") {
      e.preventDefault();
      this.togglePause();
    } else if (e.altKey && !mod && e.code === "KeyR") {
      e.preventDefault();
      this.ws.reset();
    }
  };

  activate(): void {
    this.active = true;
    document.addEventListener("keydown", this.onKey, true);
    this.applyGhost();
    this.activeView().fit(true);
  }

  deactivate(): void {
    this.active = false;
    document.removeEventListener("keydown", this.onKey, true);
    this.closeMenu();
  }

  destroy(): void {
    this.deactivate();
    this.unsubscribe();
    this.view2d.destroy();
    this.view3d?.destroy();
  }

  /** Fits the visible view to the whole drawing and resolves once that is on screen (used by the test hook). */
  async showOpened(): Promise<void> {
    this.showTab("view");
    await nextFrame();
    const view = this.activeView();
    view.fit(true);
    await nextFrame();
    view.fit(true);
    await nextFrame();
  }
}

