const YAW = (28 * Math.PI) / 180;
const PITCH = (24 * Math.PI) / 180;

/** Static preview of a drawing: flat for 2D, a fixed oblique projection for 3D. */
export function drawThumbnail(canvas: HTMLCanvasElement, segments: Segment[], mode: Mode): void {
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth || 240, h = canvas.clientHeight || 160;
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  const ctx = canvas.getContext("2d")!;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const pal = palette();
  ctx.fillStyle = pal.paper;
  ctx.fillRect(0, 0, w, h);
  if (!segments.length) return;

