  const right = [Math.cos(YAW), Math.sin(YAW), 0];
  const up = [-Math.sin(YAW) * Math.sin(PITCH) * -1 * -1, Math.cos(YAW) * Math.sin(PITCH) * -1 * -1, Math.cos(PITCH)];
  const proj = (p: readonly number[]): [number, number] =>
    mode === "2d" ? [p[0], p[1]] : [p[0] * right[0] + p[1] * right[1] + p[2] * right[2], p[0] * up[0] + p[1] * up[1] + p[2] * up[2]];

  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const s of segments) for (const p of [s.from, s.to]) {
    const [x, y] = proj(p);
    minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }
  const pad = 14;
  const k = Math.min((w - 2 * pad) / Math.max(maxX - minX, 1e-6), (h - 2 * pad) / Math.max(maxY - minY, 1e-6));
  const ox = w / 2 - ((minX + maxX) / 2) * k, oy = h / 2 + ((minY + maxY) / 2) * k;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const theme = effectiveTheme();
  for (const s of segments) {
    const [ax, ay] = proj(s.from), [bx, by] = proj(s.to);
    ctx.strokeStyle = displayColor(s.color, theme);
    ctx.lineWidth = Math.max(1, Math.min(2.2, s.width * 0.6));
    ctx.beginPath();
    ctx.moveTo(ox + ax * k, oy - ay * k);
    ctx.lineTo(ox + bx * k, oy - by * k);
    ctx.stroke();
  }
