import { CHALLENGES, ChallengeBook, type Challenge } from "../core/challenges";
import { Workspace } from "../core/workspace";
import { EXAMPLES, type Example } from "../data/examples";
import { REFERENCE, type Block, type RefCommand, type RefExample } from "../data/reference";
import { SHORTCUTS } from "../data/shortcuts";
import { run, type Mode } from "../lang";
import { confirmDialog, keyLabel, toast } from "./dialogs";
import { h, icon } from "./dom";
import { drawThumbnail } from "./thumb";
import { webglSupport } from "./view3d";

export interface PageDeps {
  ws: Workspace;
  book: ChallengeBook;
  navigate(hash: string): void;
}

const modeBadge = (mode: Mode) => h("span", { class: `badge badge-${mode}` }, mode.toUpperCase());

/** Thumbnails are redrawn when the theme changes. */
function thumb(segs: () => ReturnType<typeof run>["segments"], mode: Mode, label: string): HTMLCanvasElement {
  const canvas = h("canvas", { class: "thumb", role: "img", "aria-label": label });
  const paint = () => drawThumbnail(canvas, segs(), mode);
  requestAnimationFrame(paint);
  window.addEventListener("logomocja-theme", () => requestAnimationFrame(paint));
  new ResizeObserver(paint).observe(canvas);
  return canvas;
}

// --- Examples gallery ------------------------------------------------------------------------------------------

export function examplesPage(deps: PageDeps): HTMLElement {
  const webgl = webglSupport();
  const load = async (e: Example) => {
    if (e.mode === "3d" && !webgl.ok) {
      toast(`Przykład „${e.name}” wymaga trybu 3D. ${webgl.reason}`, "error");
      return;
    }
    let result = deps.ws.loadExample(e.id);
    if (result === "confirm") {
      const ok = await confirmDialog({
        title: `Wczytać przykład „${e.name}”?`,
        message: `Zastąpi on Twój bieżący program w trybie ${e.mode.toUpperCase()}. Poprzedni program zostanie zachowany i będzie można go przywrócić.`,
        okLabel: "Wczytaj przykład",
      });
      if (!ok) return;
      result = deps.ws.loadExample(e.id, { replace: true });
    }
    if (result === "loaded") {
      deps.navigate("#/");
      deps.ws.run();
    }
  };
  const card = (e: Example) => {
    const id = `ex-title-${e.id}`;
    return h("article", { class: "card example-card", "aria-labelledby": id },
      thumb(() => run(e.source, e.mode).segments, e.mode, `Podgląd rysunku: ${e.name}`),
      h("div", { class: "card-body" },
        h("h3", { id }, e.name, " ", modeBadge(e.mode)),
        h("p", null, e.description),
        h("button", { class: "btn primary", type: "button", "data-example": e.id, "on:click": () => load(e) }, icon("play"), `Wczytaj „${e.name}”`)));
  };
  return h("div", { class: "page" },
    h("h1", null, "Przykłady"),
    h("p", { class: "lead" }, "Trzynaście gotowych programów. Wczytaj dowolny do pracowni, uruchom go krok po kroku i zmień, co chcesz. Twój własny szkic nie zginie – przed zastąpieniem zapytamy o zgodę i zachowamy kopię."),
    h("h2", null, "Rysunki płaskie (2D)"),
    h("div", { class: "grid" }, ...EXAMPLES.filter((e) => e.mode === "2d").map(card)),
    h("h2", null, "Przestrzeń (3D)"),
    webgl.ok ? null : h("p", { class: "banner warn", role: "note" }, webgl.reason),
    h("div", { class: "grid" }, ...EXAMPLES.filter((e) => e.mode === "3d").map(card)),
  );
}

// --- Challenges list ---------------------------------------------------------------------------------------------

export function challengesPage(deps: PageDeps): HTMLElement {
  const results = deps.book.results();
  const solved = CHALLENGES.filter((c) => results[c.id]?.passed).length;
  const card = (c: Challenge) => {
    const r = results[c.id];
    const id = `ch-title-${c.id}`;
    return h("article", { class: `card challenge-card${r?.passed ? " solved" : ""}`, "aria-labelledby": id },
      thumb(() => c.target(), c.mode, `Wzór do narysowania: ${c.title}`),
      h("div", { class: "card-body" },
        h("h3", { id }, c.title, " ", modeBadge(c.mode)),
        h("p", null, c.brief),
        h("p", { class: "status-line" },
          r?.passed ? h("span", { class: "solved-mark" }, icon("check", 16), " Zaliczone") : h("span", { class: "muted" }, r ? `Niezaliczone (próby: ${r.attempts})` : "Jeszcze nie próbowano"),
        ),
        h("a", { class: "btn primary", href: `#/zadania/${c.id}` }, r?.passed ? "Rozwiąż jeszcze raz" : "Rozwiąż zadanie")));
  };
  return h("div", { class: "page" },
    h("h1", null, "Zadania"),
    h("p", { class: "lead" }, "Każde zadanie pokazuje, co narysować. Piszesz program, a Logomocja sprawdza go sama: porównuje Twój rysunek ze wzorem z tolerancją i mówi, czego brakuje albo co jest dodatkowo. Postęp zapisuje się w tej przeglądarce."),
    h("div", { class: "progress-box" },
      h("div", { class: "progress-text" }, `Zaliczone: ${solved} z ${CHALLENGES.length}`),
      h("progress", { max: CHALLENGES.length, value: solved, "aria-label": "Postęp zadań" })),
    h("div", { class: "grid" }, ...CHALLENGES.map(card)));
}

// --- Reference ---------------------------------------------------------------------------------------------------

export function referencePage(deps: PageDeps): HTMLElement {
  const tryIt = (ex: RefExample) => h("button", { class: "btn small", type: "button", "on:click": () => {
    deps.ws.loadSource(ex.code, ex.mode);
    deps.navigate("#/");
    deps.ws.run();
  } }, icon("play", 14), "Wypróbuj w pracowni");

  const codeBlock = (ex: RefExample) =>
    h("figure", { class: "example" },
      ex.caption ? h("figcaption", null, ex.caption) : null,
      h("pre", { class: "code", tabindex: 0, "aria-label": "Przykładowy program" }, h("code", null, ex.code)),
      h("div", { class: "example-actions" },
        h("span", { class: `badge badge-${ex.mode}` }, ex.mode.toUpperCase()),
        ex.expectError ? h("span", { class: "muted" }, `Błąd w wierszu ${ex.expectError.line}, kolumnie ${ex.expectError.column}`) : null,
        tryIt(ex)));

  const command = (c: RefCommand) => {
    const id = `cmd-${c.names[0]}`;
    return h("article", { class: "command", id, "aria-labelledby": `${id}-h` },
      h("h3", { id: `${id}-h` }, ...c.names.flatMap((n, i) => [i ? " · " : "", h("code", { class: "name" }, n)])),
      h("p", { class: "usage" }, h("code", null, c.usage)),
      h("p", null, c.summary),
      ...(c.details ?? []).map((d) => h("p", null, d)),
      ...c.examples.map(codeBlock));
  };

  const block = (b: Block): Node => {
    switch (b.type) {
      case "p": return h("p", null, b.text);
      case "list": return h("ul", null, ...b.items.map((i) => h("li", null, i)));
      case "code": return codeBlock(b.example);
      case "table": return h("table", { class: "ref-table" }, h("thead", null, h("tr", null, ...b.head.map((t) => h("th", { scope: "col" }, t)))), h("tbody", null, ...b.rows.map((r) => h("tr", null, ...r.map((c, i) => (i === 0 ? h("th", { scope: "row" }, c) : h("td", null, c)))))));
      case "command": return command(b);
    }
  };

  const toc = h("nav", { class: "toc", "aria-label": "Spis treści opisu poleceń" },
    h("h2", null, "Spis treści"),
    h("ol", null,
      ...REFERENCE.map((s) => h("li", null, h("a", { href: `#/polecenia`, "data-target": s.id, "on:click": (e: Event) => { e.preventDefault(); document.getElementById(`ref-${s.id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }); document.getElementById(`ref-${s.id}`)?.focus({ preventScroll: true }); } }, s.title))),
      h("li", null, h("a", { href: "#/polecenia", "on:click": (e: Event) => { e.preventDefault(); document.getElementById("ref-skroty")?.scrollIntoView({ behavior: "smooth" }); } }, "Skróty klawiszowe"))));

  const shortcuts = h("section", { class: "ref-section", id: "ref-skroty", tabindex: -1, "aria-labelledby": "ref-skroty-h" },
    h("h2", { id: "ref-skroty-h" }, "Skróty klawiszowe"),
    h("table", { class: "shortcuts" }, h("tbody", null, ...SHORTCUTS.map((s) => h("tr", null,
      h("th", { scope: "row" }, ...s.keys.flatMap((k, i) => [i ? " + " : "", h("kbd", null, keyLabel(k))])),
      h("td", null, s.action))))));

  return h("div", { class: "page reference" },
    h("h1", null, "Opis poleceń"),
    h("p", { class: "lead" }, "Pełny opis języka Logomocji: polecenia z polskimi i angielskimi nazwami, wyrażenia, zmienne, warunki, procedury, przestrzeń 3D, błędy i limity. Każdy przykład można wypróbować jednym kliknięciem."),
    toc,
    ...REFERENCE.map((s) => h("section", { class: "ref-section", id: `ref-${s.id}`, tabindex: -1, "aria-labelledby": `ref-${s.id}-h` }, h("h2", { id: `ref-${s.id}-h` }, s.title), ...s.blocks.map(block))),
    shortcuts);
}
