    h("h2", null, "Przestrzeń (3D)"),
    webgl.ok ? null : h("p", { class: "banner warn", role: "note" }, webgl.reason),
    h("div", { class: "grid" }, ...EXAMPLES.filter((e) => e.mode === "3d").map(card)),
