// --- Challenges list ---------------------------------------------------------------------------------------------

export function challengesPage(deps: PageDeps): HTMLElement {
  const results = deps.book.results();
  const solved = CHALLENGES.filter((c) => results[c.id]?.passed).length;
  const card = (c: Challenge) => {
    const r = results[c.id];
    const id = `ch-title-${c.id}`;
    return h("article", { class: `card challenge-card${r?.passed ? " solved" : ""}`, "aria-labelledby": id },
      thumb(() => c.target(), c.mode, `Wzór do narysowania: ${c.title}`),
      h("div", { class: "card-body" },
        h("h3", { id }, c.title, " ", modeBadge(c.mode)),
        h("p", null, c.brief),
        h("p", { class: "status-line" },
          r?.passed ? h("span", { class: "solved-mark" }, icon("check", 16), " Zaliczone") : h("span", { class: "muted" }, r ? `Niezaliczone (próby: ${r.attempts})` : "Jeszcze nie próbowano"),
        ),
        h("a", { class: "btn primary", href: `#/zadania/${c.id}` }, r?.passed ? "Rozwiąż jeszcze raz" : "Rozwiąż zadanie")));
  };
  return h("div", { class: "page" },
    h("h1", null, "Zadania"),
    h("p", { class: "lead" }, "Każde zadanie pokazuje, co narysować. Piszesz program, a Logomocja sprawdza go sama: porównuje Twój rysunek ze wzorem z tolerancją i mówi, czego brakuje albo co jest dodatkowo. Postęp zapisuje się w tej przeglądarce."),
    h("div", { class: "progress-box" },
