  const block = (b: Block): Node => {
    switch (b.type) {
      case "p": return h("p", null, b.text);
      case "list": return h("ul", null, ...b.items.map((i) => h("li", null, i)));
      case "code": return codeBlock(b.example);
      case "table": return h("table", { class: "ref-table" }, h("thead", null, h("tr", null, ...b.head.map((t) => h("th", { scope: "col" }, t)))), h("tbody", null, ...b.rows.map((r) => h("tr", null, ...r.map((c, i) => (i === 0 ? h("th", { scope: "row" }, c) : h("td", null, c)))))));
      case "command": return command(b);
    }
  };

  const toc = h("nav", { class: "toc", "aria-label": "Spis treści opisu poleceń" },
    h("h2", null, "Spis treści"),
    h("ol", null,
      ...REFERENCE.map((s) => h("li", null, h("a", { href: `#/polecenia`, "data-target": s.id, "on:click": (e: Event) => { e.preventDefault(); document.getElementById(`ref-${s.id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }); document.getElementById(`ref-${s.id}`)?.focus({ preventScroll: true }); } }, s.title))),
      h("li", null, h("a", { href: "#/polecenia", "on:click": (e: Event) => { e.preventDefault(); document.getElementById("ref-skroty")?.scrollIntoView({ behavior: "smooth" }); } }, "Skróty klawiszowe"))));

  const shortcuts = h("section", { class: "ref-section", id: "ref-skroty", tabindex: -1, "aria-labelledby": "ref-skroty-h" },
    h("h2", { id: "ref-skroty-h" }, "Skróty klawiszowe"),
