      h("th", { scope: "row" }, ...s.keys.flatMap((k, i) => [i ? " + " : "", h("kbd", null, keyLabel(k))])),
      h("td", null, s.action))))));

  return h("div", { class: "page reference" },
    h("h1", null, "Opis poleceń"),
    h("p", { class: "lead" }, "Pełny opis języka Logomocji: polecenia z polskimi i angielskimi nazwami, wyrażenia, zmienne, warunki, procedury, przestrzeń 3D, błędy i limity. Każdy przykład można wypróbować jednym kliknięciem."),
    toc,
    ...REFERENCE.map((s) => h("section", { class: "ref-section", id: `ref-${s.id}`, tabindex: -1, "aria-labelledby": `ref-${s.id}-h` }, h("h2", { id: `ref-${s.id}-h` }, s.title), ...s.blocks.map(block))),
    shortcuts);
}
