import { parseShare } from "./core/share";
import { Workspace } from "./core/workspace";
import { run, type Mode, type RunResult } from "./lang";
import { shortcutsDialog, toast } from "./ui/dialogs";
import { clear, h, icon } from "./ui/dom";
import { challengesPage, examplesPage, referencePage } from "./ui/pages";
import { applyTheme, savedTheme, type ThemeChoice } from "./ui/theme";
import { WorkspacePage, nextFrame } from "./ui/workspace-page";

export const VERSION = "1.0.0";

type Route = { name: "workspace" } | { name: "examples" } | { name: "challenges" } | { name: "challenge"; id: string } | { name: "reference" } | { name: "unknown" };

export function parseRoute(hash: string): Route {
  const path = hash.replace(/^#/, "").split("?")[0].replace(/\/+$/, "");
  if (path === "" || path === "/") return { name: "workspace" };
  if (path === "/przyklady") return { name: "examples" };
  if (path === "/zadania") return { name: "challenges" };
  const m = /^\/zadania\/([\w-]+)$/.exec(path);
  if (m) return { name: "challenge", id: m[1] };
  if (path === "/polecenia") return { name: "reference" };
  return { name: "unknown" };
}

const THEME_ORDER: ThemeChoice[] = ["auto", "light", "dark"];
const THEME_LABEL: Record<ThemeChoice, string> = { auto: "Motyw: według systemu", light: "Motyw: jasny", dark: "Motyw: ciemny" };

export class App {
  readonly ws: Workspace;
  readonly book: ChallengeBook;
  private root: HTMLElement;
  private main: HTMLElement;
  private nav: HTMLElement;
  private themeBtn: HTMLButtonElement;
  private mainPage: WorkspacePage;
  private current: { page?: WorkspacePage; destroy?: () => void } = {};
  private theme: ThemeChoice = savedTheme();

  constructor(root: HTMLElement) {
    this.root = root;
    this.ws = new Workspace({ storage: safeLocalStorage() });
    this.book = new ChallengeBook(safeLocalStorage());
    this.mainPage = new WorkspacePage({ ws: this.ws, navigate: (hash) => this.navigate(hash) });

    this.themeBtn = h("button", { class: "icon-btn", type: "button", "on:click": () => this.cycleTheme() });
    this.nav = h("nav", { class: "nav", "aria-label": "Główne" },
      this.navLink("#/", "Pracownia"),
      this.navLink("#/przyklady", "Przykłady"),
      this.navLink("#/zadania", "Zadania"),
      this.navLink("#/polecenia", "Polecenia"));
    const header = h("header", { class: "app-header" },
      h("a", { class: "brand", href: "#/", "aria-label": "Logomocja – strona główna (pracownia)" }, icon("turtle", 26), h("span", null, "Logomocja")),
      this.nav,
      h("div", { class: "header-tools" },
        h("button", { class: "icon-btn", type: "button", "aria-label": "Skróty klawiszowe", title: "Skróty klawiszowe", "on:click": () => shortcutsDialog() }, icon("keyboard", 20)),
        this.themeBtn));
    this.main = h("main", { class: "app-main", id: "main", tabindex: -1 });
    const skip = h("a", { class: "skip-link", href: "#main", "on:click": (e: Event) => { e.preventDefault(); this.main.focus(); } }, "Przejdź do treści");
    this.root.append(skip, header, this.main);
    this.updateThemeButton();

    window.addEventListener("hashchange", () => this.route());
    this.consumeSharedLink();
    this.route();
  }

  private navLink(href: string, label: string): HTMLAnchorElement {
    return h("a", { class: "nav-link", href, "data-href": href }, label);
  }

  navigate(hash: string): void {
    if (location.hash === hash || (hash === "#/" && (location.hash === "" || location.hash === "#"))) this.route();
    else location.hash = hash;
  }

  private cycleTheme(): void {
    this.theme = THEME_ORDER[(THEME_ORDER.indexOf(this.theme) + 1) % THEME_ORDER.length];
    applyTheme(this.theme);
    this.updateThemeButton();
    toast(THEME_LABEL[this.theme]);
  }

  private updateThemeButton(): void {
    const label = `${THEME_LABEL[this.theme]}. Kliknij, aby zmienić.`;
    this.themeBtn.setAttribute("aria-label", label);
    this.themeBtn.title = label;
    clear(this.themeBtn);
    this.themeBtn.append(icon(this.theme === "auto" ? "auto" : this.theme === "light" ? "sun" : "moon", 20));
  }

  /** A permalink in the address bar loads and runs its program once, then the URL goes back to the plain workspace. */
  private consumeSharedLink(): boolean {
    if (!parseShare(location.href)) return false;
    const result = this.ws.openLink(location.href);
    history.replaceState(null, "", location.pathname + location.search + "#/");
    if (result?.error) toast(`Program z odnośnika zawiera błąd (wiersz ${result.error.line}, kolumna ${result.error.column}).`, "error");
    else if (result) toast("Wczytano program z odnośnika i uruchomiono go.");
    return true;
  }

  private route(): void {
    if (parseShare(location.href)) this.consumeSharedLink();
    const route = parseRoute(location.hash);
    this.current.page?.deactivate();
    this.current.destroy?.();
    this.current = {};
    this.main.replaceChildren();
    const here = route.name === "challenge" ? "#/zadania" : route.name === "workspace" ? "#/" : route.name === "examples" ? "#/przyklady" : route.name === "challenges" ? "#/zadania" : route.name === "reference" ? "#/polecenia" : "";
    this.nav.querySelectorAll<HTMLAnchorElement>(".nav-link").forEach((a) => {
      const on = a.dataset.href === here;
      a.classList.toggle("active", on);
      if (on) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    });
    const deps = { ws: this.ws, book: this.book, navigate: (hash: string) => this.navigate(hash) };
    switch (route.name) {
      case "workspace":
        document.title = "Pracownia – Logomocja";
        this.main.className = "app-main is-workspace";
        this.main.append(this.mainPage.el);
        this.mainPage.activate();
        this.current = { page: this.mainPage };
        break;
      case "examples":
        document.title = "Przykłady – Logomocja";
        this.main.className = "app-main";
        this.main.append(examplesPage(deps));
        break;
      case "challenges":
        document.title = "Zadania – Logomocja";
        this.main.className = "app-main";
        this.main.append(challengesPage(deps));
        break;
      case "challenge": {
        const challenge = getChallenge(route.id);
        if (!challenge) return this.notFound();
        document.title = `${challenge.title} – zadanie – Logomocja`;
        this.main.className = "app-main is-workspace";
        const idx = CHALLENGES.indexOf(challenge);
        const next = CHALLENGES[idx + 1];
        const ws = new Workspace({ storage: safeLocalStorage(), scope: `zadanie:${challenge.id}:`, initial: { mode: challenge.mode, source: challenge.starter } });
        const page = new WorkspacePage({ ws, navigate: deps.navigate, challenge: { challenge, book: this.book, nextHref: next ? `#/zadania/${next.id}` : "#/zadania" } });
        this.main.append(page.el);
        page.activate();
        this.current = { page, destroy: () => page.destroy() };
        break;
      }
      case "reference":
        document.title = "Opis poleceń – Logomocja";
        this.main.className = "app-main";
        this.main.append(referencePage(deps));
        break;
      default:
        this.notFound();
    }
    window.scrollTo(0, 0);
  }

  private notFound(): void {
    document.title = "Nie znaleziono – Logomocja";
    this.main.className = "app-main";
    this.main.replaceChildren(h("div", { class: "page" }, h("h1", null, "Nie znaleziono strony"), h("p", null, "Takiej strony nie ma. "), h("a", { class: "btn primary", href: "#/" }, "Wróć do pracowni")));
  }

  // --- test hook ---------------------------------------------------------------------------------------------

  /** Loads `source` as if pasted, runs it to the end, fits the view and resolves when it is on screen. */
  async open(source: string, mode: Mode): Promise<RunResult> {
    if (!parseRoute(location.hash).name.startsWith("workspace")) location.hash = "#/";
    this.route();
    const result = this.ws.open(source, mode);
    await this.mainPage.showOpened();
    return { segments: result.segments, error: result.error };
  }
}

function safeLocalStorage() {
  try {
    const s = window.localStorage;
    s.getItem("logomocja:probe");
    return s;
  } catch {
    // Storage is blocked (e.g. private mode): fall back to memory so the app still works for the session.
    const mem = new Map<string, string>();
    return { getItem: (k: string) => mem.get(k) ?? null, setItem: (k: string, v: string) => void mem.set(k, v), removeItem: (k: string) => void mem.delete(k) };
  }
}

export { run, nextFrame };
