cat > serve.ts <<'EOF'
// Serves dist/ statically (no rewrites) for local checks: BASE_PATH=/sub/path/ PORT=4173 bun run serve.ts
const rawBase = process.env.BASE_PATH?.trim() || "/";
const base = (rawBase.startsWith("/") ? rawBase : "/" + rawBase).replace(/\/*$/, "/");
const port = Number(process.env.PORT) || 4173;

const server = Bun.serve({
  port,
  async fetch(req) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith(base)) return new Response("Not found", { status: 404 });
    let rel = decodeURIComponent(url.pathname.slice(base.length));
    if (rel === "" || rel.endsWith("/")) rel += "index.html";
    if (rel.includes("..")) return new Response("Bad request", { status: 400 });
    const file = Bun.file(`dist/${rel}`);
    return (await file.exists()) ? new Response(file) : new Response("Not found", { status: 404 });
  },
});
console.log(`Serving dist/ at http://localhost:${server.port}${base}`);
EOF
