import { launch } from './lib.mjs';
import fs from 'node:fs';
const URL = 'http://localhost:4173/';
const ok = (c, m) => console.log((c ? 'PASS ' : 'FAIL ') + m);
const { browser, ctx, page, logs } = await launch({ viewport: { width: 1280, height: 800 } });
await page.goto(URL);
await page.waitForSelector('.workspace');
const ta = page.locator('textarea.editor-input');

// 1. examples vs draft
await ta.fill('np 77 ; moj szkic');
await page.selectOption('select[aria-label="Wczytaj przykład"]', 'gwiazda');
await page.waitForSelector('dialog[open]');
ok(await page.locator('dialog[open] h2').innerText() === 'Wczytać przykład „Gwiazda”?', 'confirm dialog for dirty draft');
await page.click('dialog[open] button:has-text("Anuluj")');
ok((await ta.inputValue()) === 'np 77 ; moj szkic', 'cancel keeps draft');
await page.selectOption('select[aria-label="Wczytaj przykład"]', 'gwiazda');
await page.click('dialog[open] button:has-text("Wczytaj przykład")');
await page.waitForTimeout(300);
ok((await ta.inputValue()).startsWith('; Sekret gwiazdy? Kąt 144 stopni.'), 'example loaded verbatim');
ok(await page.locator('.banner.backup').count() === 1, 'backup banner visible');
await page.click('.banner.backup button:has-text("Przywróć")');
ok((await ta.inputValue()) === 'np 77 ; moj szkic', 'backup restored');

// 2. reload persistence + mode
await page.click('button.seg[data-mode="3d"]');
await ta.fill('gora 90 np 33');
await page.reload();
await page.waitForSelector('.workspace');
ok((await page.locator('textarea.editor-input').inputValue()) === 'gora 90 np 33', 'draft survives reload (3d)');
ok((await page.locator('button.seg[data-mode="3d"]').getAttribute('aria-checked')) === 'true', 'mode survives reload');
await page.click('button.seg[data-mode="2d"]');
ok((await page.locator('textarea.editor-input').inputValue()) === 'np 77 ; moj szkic', '2d draft separate');

// 3. shortcuts
await ta.fill('powtorz 20 [np 5]');
await page.locator('input.speed').fill('0'); // 1/s
await ta.press('Control+Enter');
await page.waitForTimeout(300);
ok((await page.locator('.status').innerText()).startsWith('Działa'), 'Ctrl+Enter runs');
await page.keyboard.press('Alt+KeyP');
ok((await page.locator('.status').innerText()).startsWith('Wstrzymano'), 'Alt+P pauses');
await page.keyboard.press('Alt+KeyP');
ok((await page.locator('.status').innerText()).startsWith('Działa'), 'Alt+P resumes');
await page.keyboard.press('Alt+KeyR');
ok((await page.locator('.status').innerText()).startsWith('Gotowy'), 'Alt+R resets');
await page.keyboard.press('Control+Shift+Enter');
ok((await page.locator('.status').innerText()).startsWith('Wstrzymano przed wierszem'), 'Ctrl+Shift+Enter steps');
ok(await page.locator('.band-current').evaluate((e) => !e.hidden), 'current line band shown while stepping');

// 4. share link
await ta.fill('powtorz 5 [np 40 pw 72] ; gwiazdka');
await page.click('button:has-text("Plik i udostępnianie")');
await page.click('button:has-text("Kopiuj odnośnik")');
await page.waitForSelector('dialog[open] input.share-input');
const link = await page.locator('dialog[open] input.share-input').inputValue();
ok(link.includes('#/?m=2d&p='), 'permalink format: ' + link.slice(0, 60));
await page.keyboard.press('Escape');
const p2 = await ctx.browser().newContext({ viewport: { width: 1000, height: 700 } }).then((c) => c.newPage());
await p2.goto(link);
await p2.waitForSelector('.workspace');
await p2.waitForTimeout(500);
ok((await p2.locator('textarea.editor-input').inputValue()) === 'powtorz 5 [np 40 pw 72] ; gwiazdka', 'permalink loads program');
ok((await p2.locator('.status').innerText()).startsWith('Zakończono: 5'), 'permalink runs program: ' + await p2.locator('.status').innerText());
ok(!p2.url().includes('p='), 'URL cleaned after load');

// 5. downloads
await page.click('button:has-text("Plik i udostępnianie")');
const [dl] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("Pobierz program")')]);
const path = await dl.path();
ok(dl.suggestedFilename() === 'program-2d.logo' && fs.readFileSync(path, 'utf8') === 'powtorz 5 [np 40 pw 72] ; gwiazdka', 'download .logo');
await page.click('button:has-text("Plik i udostępnianie")');
const [png] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("Pobierz rysunek")')]);
const buf = fs.readFileSync(await png.path());
ok(png.suggestedFilename() === 'rysunek-2d.png' && buf.slice(1, 4).toString() === 'PNG', 'PNG export (' + buf.length + ' bytes)');
fs.writeFileSync('/tmp/export.png', buf);
fs.writeFileSync('/tmp/upload-3d.logo', 'gora 90 np 12 ; z pliku');
await page.setInputFiles('input[type=file]', '/tmp/upload-3d.logo');
await page.waitForTimeout(300);
ok((await page.locator('textarea.editor-input').inputValue()) === 'gora 90 np 12 ; z pliku', 'open .logo file');

// 6. theme
const before = await page.evaluate(() => document.documentElement.dataset.theme ?? 'auto');
await page.click('header .icon-btn[aria-label^="Motyw"]');
const after = await page.evaluate(() => document.documentElement.dataset.theme ?? 'auto');
ok(before !== after, `theme toggles ${before} -> ${after}`);
await page.reload();
ok((await page.evaluate(() => document.documentElement.dataset.theme ?? 'auto')) === after, 'theme persists');

console.log(logs.join('\n') || 'no console issues');
await browser.close();
EOF
