cat > /tmp/tools/t7.mjs <<'EOF'
import { launch } from './lib.mjs';
import fs from 'node:fs';
const URL = 'http://localhost:4173/';
const ok = (c, m) => console.log((c ? 'PASS ' : 'FAIL ') + m);
{
  const { browser, page, logs } = await launch({ viewport: { width: 1280, height: 900 } });
  await page.goto(URL + '#/zadania');
  await page.waitForSelector('.challenge-card');
  ok((await page.locator('.progress-text').innerText()) === 'Zaliczone: 0 z 11', 'challenges list: ' + await page.locator('.progress-text').innerText());
  await page.click('a[href="#/zadania/trojkat"]');
  await page.waitForSelector('.challenge-panel');
  const ta = page.locator('textarea.editor-input');
  await ta.fill('powtorz 3 [np 100 pw 120]');
  await page.click('button:has-text("Sprawdź rozwiązanie")');
  const v1 = await page.locator('.verdict').innerText();
  ok(v1.startsWith('Jeszcze nie') && v1.includes('Brakuje') || v1.includes('nadmiar'), 'wrong solution: ' + v1);
  await page.screenshot({ path: '/tmp/e-challenge-fail.png' });
  await ta.fill('powtorz 3 [np 120 pw 120]');
  await page.click('button:has-text("Sprawdź rozwiązanie")');
  ok((await page.locator('.verdict').innerText()).startsWith('Zadanie zaliczone'), 'correct solution passes');
  await page.screenshot({ path: '/tmp/e-challenge-pass.png' });
  await page.reload();
  await page.waitForSelector('.challenge-panel');
  ok((await page.locator('textarea.editor-input').inputValue()) === 'powtorz 3 [np 120 pw 120]', 'challenge draft persisted');
  ok((await page.locator('.verdict').innerText()).startsWith('Zadanie zaliczone'), 'challenge progress persisted on page');
  await page.goto(URL + '#/zadania');
  await page.waitForSelector('.challenge-card');
  ok((await page.locator('.progress-text').innerText()) === 'Zaliczone: 1 z 11', 'list shows progress');
  // main draft untouched
  await page.goto(URL + '#/');
  ok((await page.locator('textarea.editor-input').inputValue()).startsWith('; Cztery boki'), 'main draft untouched by challenge');
  console.log(logs.join('\n') || 'no console issues');
  await browser.close();
}
{
  // WebGL unavailable
  const { browser, ctx, page, logs } = await launch({ viewport: { width: 1280, height: 800 } });
  await ctx.addInitScript(() => {
    const orig = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function (type, ...a) { if (/webgl/i.test(type)) return null; return orig.call(this, type, ...a); };
  });
  await page.goto(URL);
  await page.waitForSelector('.workspace');
  ok(await page.locator('.banner.warn').count() >= 1, 'banner explains 3D is off: ' + (await page.locator('.banner.warn').first().innerText()).slice(0, 80));
  ok(await page.locator('button.seg[data-mode="3d"]').isDisabled(), '3D button disabled');
  await page.click('.toolbar button:has-text("Uruchom")');
  await page.waitForTimeout(2500);
  ok((await page.locator('.status').innerText()).startsWith('Zakończono'), '2D still works without WebGL');
  const r = await page.evaluate(() => window.logomocja.open('gora 90 np 10', '3d'));
  ok(r.error === null && r.segments.length === 1, 'hook open(3d) still returns segments without WebGL');
  ok(await page.locator('.view-off').isVisible(), '3D panel explains');
  await page.screenshot({ path: '/tmp/e-nogl.png' });
  console.log(logs.join('\n') || 'no console issues');
  await browser.close();
}
{
  // camera interaction
  const { browser, page, logs } = await launch({ viewport: { width: 1280, height: 800 } });
  await page.goto(URL);
  await page.waitForSelector('.workspace');
  await page.evaluate(() => window.logomocja.open('kolor "#16866a"\npowtorz 4 [np 100 pw 90]\ngora 90 np 100 dol 90\npowtorz 4 [np 100 pw 90]\npowtorz 4 [np 100 dol 90 np 100 pod ws 100 opu gora 90 pw 90]', '3d'));
  await page.screenshot({ path: '/tmp/e-cube-a.png' });
  const box = await page.locator('.view3d canvas').boundingBox();
  const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
  await page.mouse.move(cx, cy); await page.mouse.down(); await page.mouse.move(cx + 150, cy - 60, { steps: 8 }); await page.mouse.up();
  await page.mouse.wheel(0, -300);
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/e-cube-b.png' });
  await page.click('button[aria-label="Zresetuj kamerę 3D"]');
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/e-cube-c.png' });
  // 2D pan and zoom
  await page.click('button.seg[data-mode="2d"]');
  await page.evaluate(() => window.logomocja.open('powtorz 36 [np 10 pw 10]', '2d'));
  const b2 = await page.locator('.view2d canvas').boundingBox();
  await page.mouse.move(b2.x + 300, b2.y + 300); await page.mouse.down(); await page.mouse.move(b2.x + 380, b2.y + 340, { steps: 5 }); await page.mouse.up();
  await page.mouse.wheel(0, -400);
  await page.waitForTimeout(200);
  await page.screenshot({ path: '/tmp/e-2d-pan.png' });
  await page.click('button[aria-label="Dopasuj widok do rysunku"]');
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/e-2d-fit.png' });
  console.log(logs.join('\n') || 'no console issues');
  await browser.close();
}
EOF
