mkdir -p /work/e2e && cat > /work/e2e/smoke.mjs <<'EOF'
// Optional browser smoke test (not part of `bun run test`).
//
//   bun run build && bun run serve.ts &          # serves dist/ at http://localhost:4173/
//   bun add -d playwright-core && bunx playwright-core install chromium
//   node e2e/smoke.mjs [baseUrl]
//
// It drives the built site in headless Chromium: the test hook, execution controls, drafts, examples,
// permalinks, file export/import, challenges, theme, keyboard shortcuts, the WebGL-off fallback and a
// scan for controls without an accessible name.
import { chromium } from "playwright-core";
import fs from "node:fs";

const BASE = process.argv[2] ?? "http://localhost:4173/";
const launchArgs = ["--no-sandbox", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"];
let failures = 0;
const check = (cond, message) => {
  if (!cond) failures++;
  console.log(`${cond ? "PASS" : "FAIL"} ${message}`);
};

async function session(options = {}, init) {
  const browser = await chromium.launch({ args: launchArgs });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, acceptDownloads: true, ...options });
  if (init) await ctx.addInitScript(init);
  const page = await ctx.newPage();
  const problems = [];
  page.on("pageerror", (e) => problems.push(e.message));
  page.on("console", (m) => m.type() === "error" && problems.push(m.text()));
  await page.goto(BASE);
  await page.waitForSelector(".workspace");
  return { browser, ctx, page, problems };
}

// --- hook, controls, drafts, examples, sharing, files ----------------------------------------------------------
{
  const { browser, ctx, page, problems } = await session();
  const editor = page.locator("textarea.editor-input");

  check(await page.evaluate(() => typeof window.logomocja.version === "string"), "window.logomocja.version");
  const pure = await page.evaluate(() => window.logomocja.run("np 10 np 1 / 0", "2d"));
  check(pure.segments.length === 1 && pure.error?.line === 1 && pure.error?.column === 14, "hook run keeps drawing before a run-time error");
  const opened = await page.evaluate(() => window.logomocja.open("powtorz 4 [np 100 pw 90]", "2d"));
  check(opened.segments.length === 4 && opened.error === null, "hook open resolves with segments");
  check((await page.locator(".status").innerText()).startsWith("Zakończono: 4"), "open ran the program on screen");

  await editor.fill("np 77 ; moj szkic");
  await page.selectOption('select[aria-label="Wczytaj przykład"]', "gwiazda");
  await page.waitForSelector("dialog[open]");
  await page.click('dialog[open] button:has-text("Anuluj")');
  check((await editor.inputValue()) === "np 77 ; moj szkic", "loading an example asks before replacing a draft");
  await page.selectOption('select[aria-label="Wczytaj przykład"]', "gwiazda");
  await page.click('dialog[open] button:has-text("Wczytaj przykład")');
  await page.click('.banner.backup button:has-text("Przywróć")');
  check((await editor.inputValue()) === "np 77 ; moj szkic", "the replaced draft can be restored");

  await page.click('button.seg[data-mode="3d"]');
  await editor.fill("gora 90 np 33");
  await page.reload();
  await page.waitForSelector(".workspace");
  check((await page.locator("textarea.editor-input").inputValue()) === "gora 90 np 33", "3D draft survives a reload");

  await page.click('button.seg[data-mode="2d"]');
  await page.locator("textarea.editor-input").fill("powtorz 20 [np 5]");
  await page.locator("input.speed").fill("0");
  await page.keyboard.press("Control+Enter");
  await page.waitForTimeout(300);
  check((await page.locator(".status").innerText()).startsWith("Działa"), "Ctrl+Enter runs");
  await page.keyboard.press("Alt+KeyP");
  check((await page.locator(".status").innerText()).startsWith("Wstrzymano"), "Alt+P pauses");
  await page.keyboard.press("Alt+KeyR");
  await page.keyboard.press("Control+Shift+Enter");
  check(await page.locator(".band-current").evaluate((e) => !e.hidden), "stepping highlights the executing line");

  await page.locator("textarea.editor-input").fill("foo");
  await page.click('.toolbar button:has-text("Uruchom")');
  check(await page.locator(".squiggle").evaluate((e) => !e.hidden), "error marker shown at the error position");

  await page.locator("textarea.editor-input").fill("powtorz 5 [np 40 pw 72]");
  await page.click('button:has-text("Plik i udostępnianie")');
  await page.click('button:has-text("Kopiuj odnośnik")');
  const link = await page.locator("dialog[open] input.share-input").inputValue();
  await page.keyboard.press("Escape");
  const other = await (await browser.newContext()).newPage();
  await other.goto(link);
  await other.waitForSelector(".workspace");
  await other.waitForTimeout(500);
  check((await other.locator(".status").innerText()).startsWith("Zakończono: 5"), "permalink opens and runs");

  await page.click('button:has-text("Plik i udostępnianie")');
  const [file] = await Promise.all([page.waitForEvent("download"), page.click('button:has-text("Pobierz program")')]);
  check(fs.readFileSync(await file.path(), "utf8") === "powtorz 5 [np 40 pw 72]", ".logo download has the program text");
  await page.click('button:has-text("Plik i udostępnianie")');
  const [png] = await Promise.all([page.waitForEvent("download"), page.click('button:has-text("Pobierz rysunek")')]);
  check(fs.readFileSync(await png.path()).subarray(1, 4).toString() === "PNG", "PNG export");

  const unnamed = await page.evaluate(() =>
    [...document.querySelectorAll("button, a[href], input, select, textarea, canvas[tabindex]")]
      .filter((el) => !el.closest("[hidden]") && getComputedStyle(el).display !== "none")
      .filter((el) => !(el.getAttribute("aria-label") || el.getAttribute("aria-labelledby") || el.textContent?.trim() || el.title || el.labels?.length))
      .map((el) => el.outerHTML.slice(0, 80)));
  check(unnamed.length === 0, `every control has an accessible name ${unnamed.join(" | ")}`);
  check(problems.length === 0, `no console errors ${problems.join(" | ")}`);
  await browser.close();
}

// --- challenges ------------------------------------------------------------------------------------------------
{
  const { browser, page, problems } = await session();
  await page.goto(BASE + "#/zadania/trojkat");
  await page.waitForSelector(".challenge-panel");
  const editor = page.locator("textarea.editor-input");
  await editor.fill("powtorz 3 [np 100 pw 120]");
  await page.click('button:has-text("Sprawdź rozwiązanie")');
  check((await page.locator(".verdict").innerText()).startsWith("Jeszcze nie"), "a wrong drawing fails with a reason");
  await editor.fill("powtorz 3 [np 120 pw 120]");
  await page.click('button:has-text("Sprawdź rozwiązanie")');
  check((await page.locator(".verdict").innerText()).startsWith("Zadanie zaliczone"), "the right drawing passes");
  await page.goto(BASE + "#/zadania");
  await page.reload();
  await page.waitForSelector(".challenge-card");
  check((await page.locator(".progress-text").innerText()).startsWith("Zaliczone: 1"), "progress persists");
  check(problems.length === 0, `no console errors ${problems.join(" | ")}`);
  await browser.close();
}

// --- WebGL unavailable --------------------------------------------------------------------------------------------
{
  const { browser, page, problems } = await session({}, () => {
    const original = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function (type, ...rest) {
      return /webgl/i.test(type) ? null : original.call(this, type, ...rest);
    };
  });
  check((await page.locator(".banner.warn").first().innerText()).includes("WebGL"), "the app says why 3D is off");
  check(await page.locator('button.seg[data-mode="3d"]').isDisabled(), "3D mode is disabled");
  await page.evaluate(() => window.logomocja.open("np 10", "2d"));
  check((await page.locator(".status").innerText()).startsWith("Zakończono"), "2D keeps working");
  check(problems.length === 0, `no console errors ${problems.join(" | ")}`);
  await browser.close();
}

console.log(failures ? `\n${failures} check(s) failed` : "\nall checks passed");
process.exit(failures ? 1 : 0);
EOF
cd /work && bun run build >/dev/null && cd /tmp/tools && . ./env.sh && cp /work/e2e/smoke.mjs ./smoke-run.mjs && node smoke-run.mjs 2>&1 | tail -40

