describe("przypadki brzegowe", () => {
  test("literał liczbowy poza zakresem liczb zmiennoprzecinkowych to błąd wykonania, a nie cichy NaN", () => {
    const huge = "1" + "0".repeat(400);
    const r = run(`np 10\npw ${huge}\nnp 10`, "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
