import { launch } from './lib.mjs';
const URL = 'http://localhost:4173/';
const ok = (c, m) => console.log((c ? 'PASS ' : 'FAIL ') + m);
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64url');
{
  const { browser, page, logs } = await launch();
  // cold start 3d permalink
  const src = 'kolor "#a478c0"\ngora 30\npowtorz 36 [np 12 pw 10]';
  await page.goto(URL + '#/?m=3d&p=' + b64(src));
  await page.waitForSelector('.workspace');
  await page.waitForTimeout(800);
  ok((await page.locator('textarea.editor-input').inputValue()) === src, '3d permalink cold start loads');
  ok((await page.locator('.status').innerText()).startsWith('Zakończono: 36'), '3d permalink runs: ' + await page.locator('.status').innerText());
  ok(page.url().endsWith('#/'), 'url cleaned: ' + page.url());
  await page.screenshot({ path: '/tmp/e-3dlink.png' });
  // hashchange path from another page
  await page.goto(URL + '#/polecenia');
  await page.waitForSelector('.command');
  await page.evaluate((h) => { location.hash = h; }, '#/?m=2d&p=' + b64('powtorz 3 [np 50 pw 120]'));
  await page.waitForSelector('.workspace');
  await page.waitForTimeout(600);
  ok((await page.locator('.status').innerText()).startsWith('Zakończono: 3'), 'hashchange permalink loads on the same tab');
  // auto-indent + undo
  await page.locator('button.seg[data-mode="2d"]').click();
  const ta = page.locator('textarea.editor-input');
  await ta.fill('');
  await ta.click();
  await page.keyboard.type('powtorz 2 [');
  await page.keyboard.press('Enter');
  await page.keyboard.type('np 5');
  await page.keyboard.press('Enter');
  await page.keyboard.type(']');
  ok((await ta.inputValue()) === 'powtorz 2 [\n  np 5\n  ]', 'auto-indent: ' + JSON.stringify(await ta.inputValue()));
  await page.keyboard.press('Control+z');
  await page.keyboard.press('Control+z');
  console.log('after 2 undos:', JSON.stringify(await ta.inputValue()));
  // keyboard focus ring
  await page.keyboard.press('Escape');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  const focus = await page.evaluate(() => { const e = document.activeElement; const cs = getComputedStyle(e); return [e.tagName, e.className, cs.outlineStyle, cs.outlineWidth]; });
  console.log('focus:', focus);
  await page.screenshot({ path: '/tmp/e-focus.png' });
  console.log(logs.join('\n') || 'no console issues');
  await browser.close();
}
{
  // touch gestures via synthetic pointer events on the 3d canvas
  const { browser, page, logs } = await launch({ viewport: { width: 390, height: 780 }, touch: true });
  await page.goto(URL);
  await page.waitForSelector('.workspace');
  await page.evaluate(() => window.logomocja.open('powtorz 4 [np 100 pw 90]\ngora 90 np 100 dol 90\npowtorz 4 [np 100 pw 90]', '3d'));
  const hash = () => page.evaluate(() => { const c = document.querySelector('.view3d canvas'); const d = c.toDataURL(); let h = 0; for (let i = 0; i < d.length; i += 97) h = (h * 31 + d.charCodeAt(i)) | 0; return h; });
  const h0 = await hash();
  const fire = (type, id, x, y) => page.evaluate(([type, id, x, y]) => {
    const c = document.querySelector('.view3d canvas'); const r = c.getBoundingClientRect();
    c.dispatchEvent(new PointerEvent(type, { pointerId: id, pointerType: 'touch', clientX: r.left + x, clientY: r.top + y, bubbles: true, isPrimary: id === 1, button: 0 }));
  }, [type, id, x, y]);
  await fire('pointerdown', 1, 150, 200); await fire('pointermove', 1, 190, 230); await fire('pointermove', 1, 230, 250); await fire('pointerup', 1, 230, 250);
  await page.waitForTimeout(200);
  const h1 = await hash();
  ok(h1 !== h0, 'one-finger drag orbits (canvas changed)');
  await fire('pointerdown', 1, 120, 200); await fire('pointerdown', 2, 220, 200);
  await fire('pointermove', 1, 90, 200); await fire('pointermove', 2, 250, 200);
  await fire('pointerup', 1, 90, 200); await fire('pointerup', 2, 250, 200);
  await page.waitForTimeout(200);
  const h2 = await hash();
  ok(h2 !== h1, 'two-finger pinch zooms (canvas changed)');
  console.log(logs.join('\n') || 'no console issues');
  await browser.close();
}
EOF
